import React, { useState, useEffect } from 'react';
import Card from '../components/Card';
import Button from '../components/Button';
import Avatar from '../components/Avatar';
import UserFormModal from '../components/UserFormModal';
import UserDeleteConfirmationModal from '../components/UserDeleteConfirmationModal';
import { EditIcon, TrashIcon, UserPlusIcon } from '../components/Icons';
import { User, UserRoleEnum } from '../types';
import { supabase } from '../supabaseClient';

const UserManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [showUserFormModal, setShowUserFormModal] = useState(false);
  const [userToEdit, setUserToEdit] = useState<User | null>(null);
  const [showDeleteConfirmationModal, setShowDeleteConfirmationModal] = useState(false);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);

  const fetchUsers = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .in('role', [UserRoleEnum.ADMIN, UserRoleEnum.MITARBEITER]); // Fetch only staff

    if (error) {
      console.error('Error fetching users:', error.message);
      alert('Fehler beim Laden der Benutzer.');
    } else {
      setUsers(data || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleOpenAddUserModal = () => {
    setUserToEdit(null);
    setShowUserFormModal(true);
  };

  const handleOpenEditUserModal = (user: User) => {
    setUserToEdit(user);
    setShowUserFormModal(true);
  };

  const handleSubmitUserForm = async (userData: { firstName: string; lastName: string; email: string; role: UserRoleEnum; }) => {
    if (userToEdit) {
      // Update existing user's profile information
      const { error } = await supabase
        .from('users')
        .update({
          firstName: userData.firstName,
          lastName: userData.lastName,
        })
        .eq('id', userToEdit.id);
      if (error) alert(error.message);

    } else {
      // Invite a new user (Mitarbeiter)
      const { error } = await supabase.auth.inviteUserByEmail(userData.email, {
        data: {
          firstName: userData.firstName,
          lastName: userData.lastName,
          role: UserRoleEnum.MITARBEITER,
        },
      });
      if (error) {
        alert(`Fehler beim Einladen des Benutzers: ${error.message}`);
      } else {
        alert(`Einladung an ${userData.email} wurde gesendet.`);
        // NOTE: You need a database trigger on 'auth.users' to create a
        // corresponding profile in your public 'users' table upon registration.
      }
    }
    setShowUserFormModal(false);
    fetchUsers(); // Refresh the list
  };

  const handleConfirmDelete = async () => {
    if (!userToDelete) return;
    // IMPORTANT: supabase.auth.admin.deleteUser requires the 'service_role' key
    // and should ONLY be called from a secure server environment (like a Supabase Edge Function).
    // Calling it from the client is a major security risk.
    // This code is for demonstration and will likely fail without a proper server-side setup.
    alert("Das Löschen von Benutzern sollte aus Sicherheitsgründen über eine Server-Funktion erfolgen. Diese Funktion ist hier nur ein Platzhalter.");

    // Placeholder for actual deletion logic (e.g., calling an Edge Function)
    // 1. Call Edge Function to delete from auth.users
    // 2. If successful, delete from public.users table
    // const { error } = await supabase.from('users').delete().eq('id', userToDelete.id);
    // if (error) alert(error.message);

    setShowDeleteConfirmationModal(false);
    setUserToDelete(null);
    fetchUsers();
  };

  const getRoleColorClass = (role: UserRoleEnum) => {
    switch (role) {
      case UserRoleEnum.ADMIN: return 'bg-red-100 text-red-800';
      case UserRoleEnum.MITARBEITER: return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="p-6 md:p-8 lg:p-10">
      <div className="flex justify-between items-center mb-2">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Mitarbeiterverwaltung</h1>
          <p className="text-gray-600">Verwalten Sie alle Mitarbeiter und Administratoren</p>
        </div>
        <Button variant="success" icon={UserPlusIcon} onClick={handleOpenAddUserModal}>
          Neuer Mitarbeiter
        </Button>
      </div>

      <Card className="mt-8">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">
          Mitarbeiter & Administratoren ({users.length})
        </h2>
        {loading ? (
            <p>Lade Benutzer...</p>
        ) : (
            <div className="divide-y divide-gray-200">
            {users.length === 0 ? (
                <p className="text-gray-500 text-sm py-4 text-center">Keine Mitarbeiter gefunden.</p>
            ) : (
                users.map(user => (
                <div key={user.id} className="flex items-center justify-between py-3">
                    <div className="flex items-center">
                    <Avatar initials={user.avatarInitials} color={user.avatarColor} size="md" className="mr-3" />
                    <div>
                        <p className="font-medium text-gray-900">{user.firstName} {user.lastName}</p>
                        <p className="text-sm text-gray-500">{user.email}</p>
                    </div>
                    </div>
                    <div className="flex items-center space-x-4">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getRoleColorClass(user.role)}`}>
                            {user.role}
                        </span>
                        <button onClick={() => handleOpenEditUserModal(user)} className="text-gray-500 hover:text-blue-600">
                            <EditIcon className="h-5 w-5" />
                        </button>
                        <button onClick={() => setUserToDelete(user); setShowDeleteConfirmationModal(true)} className="text-gray-500 hover:text-red-600">
                            <TrashIcon className="h-5 w-5" />
                        </button>
                    </div>
                </div>
                ))
            )}
            </div>
        )}
      </Card>

      <UserFormModal isOpen={showUserFormModal} onClose={() => setShowUserFormModal(false)} onSubmit={handleSubmitUserForm} userToEdit={userToEdit} />
      <UserDeleteConfirmationModal isOpen={showDeleteConfirmationModal} onClose={() => setShowDeleteConfirmationModal(false)} onConfirm={handleConfirmDelete} userNameToDelete={userToDelete ? `${userToDelete.firstName} ${userToDelete.lastName}`.trim() : ''} />
    </div>
  );
};

export default UserManagement;

import React, { useState, useEffect } from 'react';
import Modal from './Modal';
import Button from './Button';
import Input from './Input';
import { User, UserRoleEnum } from '../types';

interface UserFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (userData: { firstName: string; lastName: string; email: string; role: UserRoleEnum; }) => void;
  userToEdit: User | null;
}

const UserFormModal: React.FC<UserFormModalProps> = ({ isOpen, onClose, onSubmit, userToEdit }) => {
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  useEffect(() => {
    if (isOpen) {
      if (userToEdit) {
        setFirstName(userToEdit.firstName);
        setLastName(userToEdit.lastName);
        setEmail(userToEdit.email);
      } else {
        setFirstName('');
        setLastName('');
        setEmail('');
      }
      setErrors({});
    }
  }, [userToEdit, isOpen]);

  const validateForm = () => {
    const newErrors: { [key: string]: string } = {};
    if (!firstName.trim()) newErrors.firstName = 'Vorname ist erforderlich.';
    if (!lastName.trim()) newErrors.lastName = 'Nachname ist erforderlich.';
    if (!email.trim()) {
      newErrors.email = 'E-Mail ist erforderlich.';
    } else if (!/\S+@\S+\.\S+/.test(email)) {
      newErrors.email = 'Ungültiges E-Mail-Format.';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validateForm()) {
      onSubmit({
        firstName,
        lastName,
        email,
        role: UserRoleEnum.MITARBEITER, // This form is for creating/editing employees
      });
    }
  };

  const title = userToEdit ? 'Mitarbeiter bearbeiten' : 'Neuen Mitarbeiter einladen';

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={title} className="max-w-md">
      <form onSubmit={handleSubmit} className="p-0">
        <div className="space-y-4">
          <Input id="userFirstName" label="Vorname" type="text" value={firstName} onChange={(e) => setFirstName(e.target.value)} placeholder="Max" error={errors.firstName} />
          <Input id="userLastName" label="Nachname" type="text" value={lastName} onChange={(e) => setLastName(e.target.value)} placeholder="Mustermann" error={errors.lastName} />
          <Input id="userEmail" label="E-Mail" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="max.mustermann@example.com" error={errors.email} disabled={!!userToEdit} />
          {!userToEdit && <p className="text-sm text-gray-500">Der Benutzer erhält eine Einladung per E-Mail, um sein Konto einzurichten und ein Passwort festzulegen.</p>}
        </div>
        <div className="p-4 border-t border-gray-200 mt-6 flex justify-end space-x-3">
          <Button variant="outline" onClick={onClose} type="button">
            Abbrechen
          </Button>
          <Button variant="success" type="submit">
            {userToEdit ? 'Speichern' : 'Einladung senden'}
          </Button>
        </div>
      </form>
    </Modal>
  );
};

export default UserFormModal;

import { NavigationItem } from './types';
import { HomeIcon, UsersIcon, ClipboardIcon, SettingsIcon } from './components/Icons';

export const NAVIGATION_ITEMS: NavigationItem[] = [
  { path: '/', label: 'Übersicht', icon: HomeIcon },
  { path: '/customers', label: 'Kunden', icon: UsersIcon },
  { path: '/reports', label: 'Berichte', icon: ClipboardIcon },
  { path: '/users', label: 'Benutzer', icon: SettingsIcon },
];

export const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');

// These constants are for UI filter options, not for data.
export const MOCK_REPORT_TYPES = ['Monatlich', 'Jährlich', 'Benutzerdefiniert'];
export const MOCK_REPORT_EMPLOYEES = ['Alle Mitarbeiter']; // This should be populated dynamically from users in a future update
export const MOCK_TRANSACTION_FILTERS = ['Alle Transaktionen', 'Einnahmen (Aufladungen)', 'Ausgaben (Abbuchungen)'];

