    }
    setShowUserFormModal(false);
    fetchUsers(); // Refresh the list
  };

  const handleConfirmDelete = async () => {
    if (!userToDelete) return;
    // IMPORTANT: supabase.auth.admin.deleteUser requires the 'service_role' key
    // and should ONLY be called from a secure server environment (like a Supabase Edge Function).
    // Calling it from the client is a major security risk.
    // This code is for demonstration and will likely fail without a proper server-side setup.
    alert("Das Löschen von Benutzern sollte aus Sicherheitsgründen über eine Server-Funktion erfolgen. Diese Funktion ist hier nur ein Platzhalter.");

    // Placeholder for actual deletion logic (e.g., calling an Edge Function)
    // 1. Call Edge Function to delete from auth.users
    // 2. If successful, delete from public.users table
    // const { error } = await supabase.from('users').delete().eq('id', userToDelete.id);
    // if (error) alert(error.message);

    setShowDeleteConfirmationModal(false);
    setUserToDelete(null);
    fetchUsers();
  };

  const getRoleColorClass = (role: UserRoleEnum) => {
    switch (role) {
      case UserRoleEnum.ADMIN: return 'bg-red-100 text-red-800';
      case UserRoleEnum.MITARBEITER: return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
