      </Card>

      <UserFormModal isOpen={showUserFormModal} onClose={() => setShowUserFormModal(false)} onSubmit={handleSubmitUserForm} userToEdit={userToEdit} />
      <UserDeleteConfirmationModal isOpen={showDeleteConfirmationModal} onClose={() => setShowDeleteConfirmationModal(false)} onConfirm={handleConfirmDelete} userNameToDelete={userToDelete ? `${userToDelete.firstName} ${userToDelete.lastName}`.trim() : ''} />
    </div>
  );
};

