                <QRCodeDisplay dataUrl={customer.qrCodeData} className="mb-3" />
            </Card>
        </div>
      </div>

      {/* Modals */}
      <TransactionConfirmationModal isOpen={showConfirmationModal} onClose={() => setShowConfirmationModal(false)} onConfirm={handleConfirmTransaction} data={transactionData} />
      <TransactionTypeSelectionModal isOpen={showTransactionTypeModal} onClose={() => setShowTransactionTypeModal(false)} onSelectType={(type) => handleOpenConfirmationModal(type === 'Aufladung' ? 215 : 18, type, type === 'Aufladung' ? 'Aufladung' : 'Trails')} />
      <CustomerFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSubmit={handleUpdateStammdaten} customerToEdit={customer} />
      <TransactionHistoryModal isOpen={isTransactionHistoryModalOpen} onClose={() => setIsTransactionHistoryModalOpen(false)} transactions={transactions} customerName={`${customer.firstName} ${customer.lastName}`} />
    </div>
  );
};

