import React, { useState } from 'react';
import Card from '../components/Card';
import Input from '../components/Input';
import Button from '../components/Button';
import { supabase } from '../supabaseClient';
import { UserRoleEnum } from '../types';

const LoginPage: React.FC = () => {
  const [isRegisterMode, setIsRegisterMode] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [confirmPasswordError, setConfirmPasswordError] = useState('');
  const [apiError, setApiError] = useState('');
  const [loading, setLoading] = useState(false);
  const [infoMessage, setInfoMessage] = useState('');

  const resetForm = (switchToRegister: boolean) => {
    setIsRegisterMode(switchToRegister);
    setEmail('');
    setPassword('');
    setConfirmPassword('');
    setEmailError('');
    setPasswordError('');
    setConfirmPasswordError('');
    setApiError('');
    setInfoMessage('');
  };

  const validateForm = () => {
    let isValid = true;
    setEmailError('');
    setPasswordError('');
    setConfirmPasswordError('');
    setApiError('');
    setInfoMessage('');

    if (!email.trim()) {
      setEmailError('E-Mail ist erforderlich.');
      isValid = false;
    } else if (!/\S+@\S+\.\S+/.test(email)) {
      setEmailError('Ungültiges E-Mail-Format.');
      isValid = false;
    }

    if (!password.trim()) {
      setPasswordError('Passwort ist erforderlich.');
      isValid = false;
    } else if (password.length < 6) {
      setPasswordError('Passwort muss mindestens 6 Zeichen lang sein.');
      isValid = false;
    }

    if (isRegisterMode) {
      if (password !== confirmPassword) {
        setConfirmPasswordError('Die Passwörter stimmen nicht überein.');
        isValid = false;
      }
    }

    return isValid;
  };

  const handleLogin = async () => {
    setLoading(true);
    setApiError('');
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) {
      setApiError('Ungültige E-Mail oder ungültiges Passwort.');
    }
    // onAuthStateChange in App.tsx will handle successful navigation
    setLoading(false);
  };

  const handleRegister = async () => {
    setLoading(true);
    setApiError('');
    setInfoMessage('');

    // A database trigger should be set up in Supabase to create a corresponding
    // customer and user profile entry upon new user registration.
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          // This data is passed to the database trigger to populate the initial profile.
          // Using static placeholders is more reliable than deriving from the email.
          firstName: 'Neuer',
          lastName: 'Kunde',
          role: UserRoleEnum.KUNDE,
        },
      },
    });

    if (error) {
      setApiError(error.message);
    } else if (data.user && data.user.identities && data.user.identities.length === 0) {
      // Supabase sometimes returns a user object for an existing, unconfirmed user.
      setApiError("Ein Benutzer mit dieser E-Mail existiert bereits, wurde aber nicht bestätigt.");
    } else if (data.session) {
      // User is logged in immediately
      setInfoMessage('Registrierung erfolgreich! Sie werden weitergeleitet...');
    } else {
      // User needs to confirm their email
      setInfoMessage('Registrierung erfolgreich! Bitte überprüfen Sie Ihre E-Mail, um Ihr Konto zu bestätigen.');
      setIsRegisterMode(false); // Switch back to login view
    }
    setLoading(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (validateForm()) {
      if (isRegisterMode) {
        await handleRegister();
      } else {
        await handleLogin();
      }
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen w-full bg-gray-100 p-4">
      <Card className="max-w-md w-full p-8">
        <h1 className="text-3xl font-bold text-gray-900 text-center mb-6">Mantrailing Card</h1>
        <p className="text-gray-600 text-center mb-8">
          {isRegisterMode ? 'Erstellen Sie Ihr neues Kundenkonto' : 'Melden Sie sich an, um fortzufahren'}
        </p>

        <form onSubmit={handleSubmit} className="space-y-6">
          <Input
            id="loginEmail"
            label="E-Mail"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="ihre.email@example.com"
            error={emailError}
            disabled={loading}
          />
          <Input
            id="loginPassword"
            label="Passwort"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="********"
            error={passwordError}
            disabled={loading}
          />
          {isRegisterMode && (
            <Input
              id="confirmPassword"
              label="Passwort bestätigen"
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="********"
              error={confirmPasswordError}
              disabled={loading}
            />
          )}

          {apiError && (
            <div className="text-red-600 text-sm text-center -mt-4 bg-red-50 p-2 rounded-md">
              {apiError}
            </div>
          )}

          {infoMessage && (
            <div className="text-green-700 text-sm text-center -mt-4 bg-green-50 p-2 rounded-md">
              {infoMessage}
            </div>
          )}

          <Button type="submit" variant="primary" className="w-full" disabled={loading}>
            {loading ? 'Bitte warten...' : (isRegisterMode ? 'Registrieren' : 'Anmelden')}
          </Button>
        </form>

        <div className="text-center mt-6">
          <button onClick={() => resetForm(!isRegisterMode)} className="text-sm text-blue-600 hover:underline" disabled={loading}>
            {isRegisterMode ? 'Bereits ein Konto? Jetzt anmelden' : 'Noch kein Konto? Jetzt registrieren'}
          </button>
        </div>
      </Card>
    </div>
  );
};

export default LoginPage;

