import Card from '../components/Card';
import StatCard from '../components/StatCard';
import Table, { Column } from '../components/Table';
import Button from '../components/Button';
import Avatar from '../components/Avatar';
import { ChevronRightIcon, UsersIcon, HeartIcon, ClipboardIcon, RepeatIcon, UserPlusIcon } from '../components/Icons';
import { ALPHABET } from '../constants';
import { Customer, CustomerTableData, TrainingLevelEnum, Transaction, User, UserRoleEnum } from '../types';
import { useNavigate } from 'react-router-dom';
import { parseDateString, isSameMonth } from '../utils';

interface CustomerManagementProps {
  currentUser: User;
  customers: Customer[];
  transactions: Transaction[];
}

// Helper function to get color classes based on training level for the badge
const getLevelColorClass = (level: TrainingLevelEnum) => {
  switch (level) {
    case TrainingLevelEnum.EINSTEIGER:
      return 'bg-fuchsia-100 text-fuchsia-800'; // Orchid
    case TrainingLevelEnum.GRUNDLAGEN:
      return 'bg-lime-100 text-lime-800'; // Lime Green
    case TrainingLevelEnum.FORTGESCHRITTENE:
      return 'bg-sky-100 text-sky-800'; // Sky Blue
    case TrainingLevelEnum.MASTERCLASS:
      return 'bg-amber-100 text-amber-800'; // Peru
    case TrainingLevelEnum.EXPERT:
      return 'bg-indigo-100 text-indigo-800'; // Indigo
    default:
      return 'bg-gray-100 text-gray-800'; // Default
  }
};

// Helper function to get color classes based on training level for the avatar circle
const getAvatarColorForLevel = (level: TrainingLevelEnum) => {
  switch (level) {
    case TrainingLevelEnum.EINSTEIGER:
      return 'bg-fuchsia-500'; // Orchid (500-level for stronger color on avatar)
    case TrainingLevelEnum.GRUNDLAGEN:
      return 'bg-lime-500'; // Lime Green
    case TrainingLevelEnum.FORTGESCHRITTENE:
      return 'bg-sky-500'; // Sky Blue
    case TrainingLevelEnum.MASTERCLASS:
      return 'bg-amber-500'; // Peru
    case TrainingLevelEnum.EXPERT:
      return 'bg-indigo-500'; // Indigo
    default:
      return 'bg-gray-400'; // Default (a neutral grey)
  }
};

const CustomerManagement: React.FC<CustomerManagementProps> = ({ currentUser, customers, transactions }) => {
  const navigate = useNavigate();
  const [activeFilter, setActiveFilter] = useState<string>('Alle');

  // Dynamic calculations for Customer Management Stats
  const totalCustomers = customers.length;
  const totalBalance = customers.reduce((sum, c) => sum + c.balance, 0);

  const today = new Date();
  const currentMonthTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    return transactionDate && isSameMonth(transactionDate, today);
  });
  const monthlyTransactionsCount = currentMonthTransactions.length;

  // Determine active customers (those with transactions in the current month)
  const activeCustomerIds = new Set(
    currentMonthTransactions.map(t => t.customerId)
  );
  const activeCustomersCount = customers.filter(c => activeCustomerIds.has(c.id)).length;

  const filteredCustomers = customers.filter((customer) => {
    if (activeFilter === 'Alle') {
      return true;
    }
    return customer.lastName.startsWith(activeFilter);
  });

  const customerTableData: CustomerTableData[] = filteredCustomers.map((customer) => ({
    id: customer.id,
    avatarInitials: customer.avatarInitials,
    avatarColor: customer.avatarColor,
    name: `${customer.firstName} ${customer.lastName}`,
    dog: customer.dogName,
    balance: customer.balance,
    level: customer.level,
    createdAt: customer.createdAt,
  }));

  const columns: Column<CustomerTableData>[] = [
    {
      key: 'name',
      header: 'Kunde',
      render: (item: CustomerTableData) => (
        <div className="flex items-center">
          <Avatar
            initials={item.avatarInitials}
            color={getAvatarColorForLevel(item.level)}
            size="md"
            className="mr-3"
          />
          <div>
            <p className="font-medium text-gray-900">{item.name}</p>
            <p className="text-sm text-gray-500">{customers.find(c=>c.id === item.id)?.email}</p>
          </div>
        </div>
      ),
    },
    { key: 'dog', header: 'Hund' },
    {
      key: 'balance',
      header: 'Guthaben',
      render: (item: CustomerTableData) => item.balance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }),
    },
    {
      key: 'level',
      header: 'Level',
      render: (item: CustomerTableData) => (
        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getLevelColorClass(item.level)}`}>
          {item.level}
        </span>
      ),
    },
    { key: 'createdAt', header: 'Erstellt' },
    {
      key: 'id',
      header: '',
      render: () => <ChevronRightIcon className="h-5 w-5 text-gray-400" />,
      className: 'text-right',
    },
  ];

  const handleRowClick = (customerData: CustomerTableData) => {
    navigate(`/customers/${customerData.id}`);
  };

  const canCreateCustomer = currentUser.role === UserRoleEnum.ADMIN || currentUser.role === UserRoleEnum.MITARBEITER;

  return (
    <div className="p-6 md:p-8 lg:p-10">
      <div className="flex justify-between items-center mb-2">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Kundenverwaltung</h1>
          <p className="text-gray-600">Verwalten Sie alle Ihre Kunden an einem Ort</p>
        </div>
        {canCreateCustomer && (
          <Button variant="success" icon={UserPlusIcon} onClick={() => alert('Funktion zum Hinzufügen von Kunden wird implementiert.')}>
            Neuer Kunde
          </Button>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 my-8">
        <StatCard title="Kunden Gesamt" value={totalCustomers} icon={UsersIcon} color="bg-green-100 text-green-700" />
        <StatCard title="Aktiv" value={activeCustomersCount} icon={HeartIcon} color="bg-orange-100 text-orange-700" />
        <StatCard title="Guthaben" value={totalBalance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })} icon={ClipboardIcon} color="bg-blue-100 text-blue-700" />
        <StatCard title="Transaktionen Monat" value={monthlyTransactionsCount} icon={RepeatIcon} color="bg-purple-100 text-purple-700" />
      </div>

      <Card className="mb-6 px-4 py-2">
        <div className="flex flex-wrap justify-between gap-2">
          <button
            onClick={() => setActiveFilter('Alle')}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors
              ${activeFilter === 'Alle' ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
          >
            Alle
          </button>
          {ALPHABET.map((letter) => (
            <button
              key={letter}
              onClick={() => setActiveFilter(letter)}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors
                ${activeFilter === letter ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </Card>

      <Card>
        <h2 className="text-xl font-semibold text-gray-900 mb-4">Kundenliste ({filteredCustomers.length})</h2>
        {customerTableData.length > 0 ? (
            <Table data={customerTableData} columns={columns} onRowClick={handleRowClick} />
        ) : (
            <p className="text-gray-500 py-4">Keine Kunden gefunden. Erstellen Sie Ihren ersten Kunden!</p>
        )}
      </Card>
    </div>
  );
};

export default CustomerManagement;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Card from '../components/Card';
import Avatar from '../components/Avatar';
import Button from '../components/Button';
import Input from '../components/Input';
import QRCodeDisplay from '../components/QRCodeDisplay';
import TransactionConfirmationModal from '../components/TransactionConfirmationModal';
import TransactionTypeSelectionModal from '../components/TransactionTypeSelectionModal';
import CustomerFormModal from '../components/CustomerFormModal';
import TransactionHistoryModal from '../components/TransactionHistoryModal';
import {
  ArrowLeftIcon,
  HeartIcon,
  CreditCardIcon,
  MailIcon,
  PhoneIcon,
  UserIcon,
  ChevronDownIcon,
  EditIcon,
  SaveIcon,
  ClipboardIcon,
} from '../components/Icons';
import { Customer, TransactionConfirmationData, Transaction, User, UserRoleEnum, NewCustomerData } from '../types';

interface TrainingHourCircleProps {
  filled: boolean;
  className?: string;
}

const TrainingPawIcon: React.FC<TrainingHourCircleProps> = ({ filled, className = '' }) => (
  <div
    className={`flex items-center justify-center h-12 w-12 rounded-full border transition-all duration-300
      ${filled ? 'bg-green-100 border-green-300' : 'bg-gray-50 border-gray-200'}
      ${className}`}
  >
    <img
      src="https://hs-bw.com/wp-content/uploads/2025/12/Suchund-Icon.png"
      alt="Paw Icon"
      className={`h-8 w-8 object-contain ${!filled ? 'grayscale opacity-50' : ''}`}
    />
  </div>
);

interface CustomerDetailsProps {
  currentUser: User;
  customers: Customer[];
  transactions: Transaction[];
  onUpdateCustomer: (customer: Customer) => void;
  onAddTransaction: (transaction: Omit<Transaction, 'id'>) => void;
}

const CustomerDetails: React.FC<CustomerDetailsProps> = ({ currentUser, customers, transactions, onUpdateCustomer, onAddTransaction }) => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [customerTransactions, setCustomerTransactions] = useState<Transaction[]>([]);

  // Modal states
  const [showConfirmationModal, setShowConfirmationModal] = useState(false);
  const [showTransactionTypeModal, setShowTransactionTypeModal] = useState(false);
  const [isTransactionHistoryModalOpen, setIsTransactionHistoryModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [transactionData, setTransactionData] = useState<TransactionConfirmationData | null>(null);

  // Edit mode for customer self-service
  const [isEditMode, setIsEditMode] = useState(false);
  const [editableData, setEditableData] = useState({
    firstName: '',
    lastName: '',
    phone: '',
    dogName: '',
    chipNumber: '',
  });

  const [expandedSections, setExpandedSections] = useState<Record<number, boolean>>({});

  useEffect(() => {
    const customerId = parseInt(id || '0', 10);
    if (currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId && customerId !== currentUser.associatedCustomerId) {
        navigate(`/customers/${currentUser.associatedCustomerId}`, { replace: true });
        return;
    }

    const foundCustomer = customers.find(c => c.id === customerId);
    if (foundCustomer) {
      setCustomer(foundCustomer);
      setEditableData({
        firstName: foundCustomer.firstName,
        lastName: foundCustomer.lastName,
        phone: foundCustomer.phone,
        dogName: foundCustomer.dogName,
        chipNumber: foundCustomer.chipNumber,
      });

      const customerTrans = transactions.filter(t => t.customerId === customerId);
      setCustomerTransactions(customerTrans);

      const initialExpansionState: Record<number, boolean> = {};
      foundCustomer.trainingProgress.forEach(section => {
        initialExpansionState[section.id] = section.status === 'Aktuell';
      });
      setExpandedSections(initialExpansionState);
    } else {
      setCustomer(null);
    }
  }, [id, customers, transactions, currentUser, navigate]);

  const handleOpenConfirmationModal = (amount: number, type: 'Aufladung' | 'Abbuchung', description?: string) => {
    if (!customer) return;
    const oldBalance = customer.balance;
    const newBalance = type === 'Aufladung' ? oldBalance + amount : oldBalance - amount;
    setTransactionData({
      customerId: customer.id,
      customerName: `${customer.firstName} ${customer.lastName}`,
      employee: `${currentUser.firstName} ${currentUser.lastName}`,
      transactionType: type,
      amount: amount,
      oldBalance: oldBalance,
      newBalance: newBalance,
      description: description,
    });
    setShowConfirmationModal(true);
  };

  const handleConfirmTransaction = () => {
    if (!transactionData || !customer) return;

    let updatedTrainingProgress = [...(customer.trainingProgress || [])];

    if (transactionData.transactionType === 'Abbuchung') {
      const currentSectionIndex = updatedTrainingProgress.findIndex(s => s.status === 'Aktuell');

      if (currentSectionIndex !== -1) {
        const currentSection = { ...updatedTrainingProgress[currentSectionIndex] };
        currentSection.completedHours += 1;

        if (currentSection.completedHours >= currentSection.requiredHours) {
          currentSection.status = 'Abgeschlossen';
          const nextSectionIndex = currentSectionIndex + 1;
          if (nextSectionIndex < updatedTrainingProgress.length) {
            updatedTrainingProgress[nextSectionIndex] = { ...updatedTrainingProgress[nextSectionIndex], status: 'Aktuell' };
          }
        }
        updatedTrainingProgress[currentSectionIndex] = currentSection;
      }
    }

    const newLevel = updatedTrainingProgress.find(s => s.status === 'Aktuell')?.name || customer.level;

    const updatedCustomer: Customer = { 
      ...customer,
      balance: transactionData.newBalance,
      totalTransactions: customer.totalTransactions + 1,
      trainingProgress: updatedTrainingProgress,
      level: newLevel
    };

    const newTransaction: Omit<Transaction, 'id'> = {
      customerId: customer.id,
      type: transactionData.transactionType === 'Aufladung' ? 'recharge' : 'debit',
      description: transactionData.description || 'Keine Beschreibung',
      amount: transactionData.amount,
      date: new Date().toLocaleDateString('de-DE'),
      employee: transactionData.employee,
    };

    onUpdateCustomer(updatedCustomer);
    onAddTransaction(newTransaction);

    setShowConfirmationModal(false);
    setTransactionData(null);
  };

  const handleSaveChanges = () => {
    if (!customer) return;
    onUpdateCustomer({
      ...customer,
      firstName: editableData.firstName,
      lastName: editableData.lastName,
      phone: editableData.phone,
      dogName: editableData.dogName,
      chipNumber: editableData.chipNumber,
    });
    setIsEditMode(false);
  };

  const handleUpdateStammdaten = (data: NewCustomerData) => {
    if (!customer) return;
    onUpdateCustomer({ ...customer, ...data });
    setIsEditModalOpen(false);
  };

  if (!customer) {
    return (
      <div className="p-8 text-center text-gray-600">
        Kunde mit ID "{id}" nicht gefunden.
        <Button variant="primary" onClick={() => navigate('/customers')} className="mt-4">
          Zurück zur Kundenliste
        </Button>
      </div>
    );
  }

  const getStatusClasses = (status: string) => {
    switch (status) {
      case 'Aktuell': return 'bg-green-100 text-green-800';
      case 'Gesperrt': return 'bg-red-100 text-red-800';
      case 'Abgeschlossen': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const DataRow: React.FC<{ Icon: React.ElementType; label: string; value: string | number }> = ({ Icon, label, value }) => (
    <div>
      <div className="flex items-center text-gray-500 mb-1">
        <Icon className="h-4 w-4 mr-2" />
        <span className="text-sm font-medium">{label}</span>
      </div>
      <p className="font-semibold text-gray-900 ml-6">{value || '-'}</p>
    </div>
  );

  const toggleSection = (sectionId: number) => {
    setExpandedSections(prev => ({ ...prev, [sectionId]: !prev[sectionId] }));
  };

  const canPerformActions = currentUser.role === UserRoleEnum.ADMIN || currentUser.role === UserRoleEnum.MITARBEITER;
  const isCustomerViewing = currentUser.role === UserRoleEnum.KUNDE;

  return (
    <div className="p-6 md:p-8 lg:p-10 min-h-screen">
       <div className="flex items-center justify-between mb-6 flex-wrap gap-4">
        <div className="flex items-center">
          {!isCustomerViewing && (
            <button onClick={() => navigate('/customers')} className="text-gray-500 hover:text-gray-700 mr-4">
              <ArrowLeftIcon className="h-6 w-6" />
            </button>
          )}
          <h1 className="text-2xl font-bold text-gray-900 flex items-center">
            {customer.firstName} {customer.lastName}
          </h1>
        </div>

        {isEditMode ? (
          <div className="flex space-x-3">
            <Button variant="outline" onClick={() => setIsEditMode(false)}>Abbrechen</Button>
            <Button variant="success" icon={SaveIcon} onClick={handleSaveChanges}>Speichern</Button>
          </div>
        ) : (
          <div className="flex space-x-3">
            {!isCustomerViewing && canPerformActions && (
              <>
                <Button variant="outline" onClick={() => setIsEditModalOpen(true)}>Stammdaten</Button>
                <Button variant="success" onClick={() => setShowTransactionTypeModal(true)}>Transaktionen</Button>
              </>
            )}
            {isCustomerViewing && (
              <Button variant="primary" icon={EditIcon} onClick={() => setIsEditMode(true)}>Meine Daten bearbeiten</Button>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
            <Card>
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Persönliche Daten</h2>
                <div className="flex flex-col sm:flex-row items-start">
                    <Avatar initials={customer.avatarInitials} color={customer.avatarColor} size="lg" className="mr-6 mb-4 sm:mb-0 flex-shrink-0" />
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-12 gap-y-6 flex-grow">
                        {isEditMode ? <Input id="firstName" label="Vorname" value={editableData.firstName} onChange={(e) => setEditableData(p => ({...p, firstName: e.target.value}))} /> : <DataRow Icon={UserIcon} label="Vorname" value={customer.firstName} />}
                        {isEditMode ? <Input id="lastName" label="Nachname" value={editableData.lastName} onChange={(e) => setEditableData(p => ({...p, lastName: e.target.value}))} /> : <DataRow Icon={UserIcon} label="Nachname" value={customer.lastName} />}
                        <DataRow Icon={MailIcon} label="E-Mail" value={customer.email} />
                        {isEditMode ? <Input id="phone" label="Telefon" value={editableData.phone} onChange={(e) => setEditableData(p => ({...p, phone: e.target.value}))} /> : <DataRow Icon={PhoneIcon} label="Telefon" value={customer.phone} />}
                        {isEditMode ? <Input id="dogName" label="Hund" value={editableData.dogName} onChange={(e) => setEditableData(p => ({...p, dogName: e.target.value}))} /> : <DataRow Icon={HeartIcon} label="Hund" value={customer.dogName} />}
                        {isEditMode ? <Input id="chipNumber" label="Chipnummer" value={editableData.chipNumber} onChange={(e) => setEditableData(p => ({...p, chipNumber: e.target.value}))} /> : <DataRow Icon={CreditCardIcon} label="Chipnummer" value={customer.chipNumber} />}
                    </div>
                </div>
            </Card>
             <Card>
                <h2 className="text-xl font-semibold text-gray-900 mb-4">Ausbildungsfortschritt</h2>
                 <div className="space-y-2">
                  {(customer.trainingProgress || []).map((section) => {
                    const isExpanded = expandedSections[section.id];
                    return (
                      <div key={section.id} className="border rounded-lg overflow-hidden">
                        <button
                          className={`p-4 flex items-center justify-between w-full text-left bg-gray-50 hover:bg-gray-100 transition-colors`}
                          onClick={() => toggleSection(section.id)}
                        >
                          <h3 className="text-lg font-medium text-gray-900">{section.name}</h3>
                          <div className="flex items-center">
                            <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${getStatusClasses(section.status)} mr-4`}>{section.status}</span>
                            <ChevronDownIcon className={`h-5 w-5 text-gray-500 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
                          </div>
                        </button>
                        <div className={`${isExpanded ? 'max-h-96' : 'max-h-0'} overflow-hidden transition-all duration-500 ease-in-out`}>
                           <div className="p-4 bg-white flex flex-wrap gap-3">
                             {Array.from({ length: section.requiredHours }, (_, i) => (
                               <TrainingPawIcon key={i} filled={i < section.completedHours} />
                             ))}
                           </div>
                        </div>
                      </div>
                    );
                  })}
                 </div>
            </Card>
        </div>
         <div className="lg:col-span-1 space-y-6">
            <Card>
              <h2 className="text-xl font-semibold text-gray-900 mb-4">Kundenkarte</h2>
              <div className="space-y-4">
                <div>
                  <p className="text-sm font-medium text-gray-500">Aktuelles Guthaben</p>
                  <p className="text-4xl font-bold text-blue-600">{customer.balance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}</p>
                </div>
                <div>
                  <p className="text-sm font-medium text-gray-500">Ausbildungslevel</p>
                  <p className="text-2xl font-semibold text-gray-800">{customer.level}</p>
                </div>
                <div className="pt-4 border-t">
                  { (canPerformActions) &&
                    <div className="flex flex-col space-y-3">
                      <Button variant="success" onClick={() => setShowTransactionTypeModal(true)}>Transaktionen</Button>
                      <Button variant="outline" onClick={() => setIsTransactionHistoryModalOpen(true)}>Transaktionshistorie</Button>
                    </div>
                  }
                  { isCustomerViewing &&
                    <Button variant="primary" icon={ClipboardIcon} onClick={() => setIsTransactionHistoryModalOpen(true)} className="w-full">
                      Meine Transaktionshistorie
                    </Button>
                  }
                </div>
              </div>
            </Card>
            <Card>
                <h2 className="text-xl font-semibold text-gray-900 mb-4">QR-Code</h2>
                <QRCodeDisplay dataUrl={customer.qrCodeData} className="mb-3" />
            </Card>
        </div>
      </div>

      {/* Modals */}
      <TransactionConfirmationModal isOpen={showConfirmationModal} onClose={() => setShowConfirmationModal(false)} onConfirm={handleConfirmTransaction} data={transactionData} />
      <TransactionTypeSelectionModal isOpen={showTransactionTypeModal} onClose={() => setShowTransactionTypeModal(false)} onSelectType={(type) => handleOpenConfirmationModal(type === 'Aufladung' ? 215 : 18, type, type === 'Aufladung' ? 'Aufladung' : 'Trails')} />
      <CustomerFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSubmit={handleUpdateStammdaten} customerToEdit={customer} />
      <TransactionHistoryModal isOpen={isTransactionHistoryModalOpen} onClose={() => setIsTransactionHistoryModalOpen(false)} transactions={customerTransactions} customerName={`${customer.firstName} ${customer.lastName}`} />
    </div>
  );
};

export default CustomerDetails;

import React, { useState, useEffect } from 'react';
import Card from '../components/Card';
import StatCard from '../components/StatCard';
import Button from '../components/Button';
import Select from '../components/Select';
import Avatar from '../components/Avatar';
import { MOCK_REPORT_TYPES, MOCK_REPORT_EMPLOYEES, MOCK_TRANSACTION_FILTERS } from '../constants';
import { ArrowUpCircleIcon, ArrowDownCircleIcon, DollarSignIcon, ClipboardIcon, UsersIcon } from '../components/Icons';
import { parseDateString, isSameMonth } from '../utils';
import { Customer, Transaction } from '../types';

import jsPDF from 'jspdf';
import 'jspdf-autotable';

interface ReportsProps {
  customers: Customer[];
  transactions: Transaction[];
}

const generateReportPeriods = (reportType: string, referenceDate: Date) => {
    const periods = [];
    const currentMonthName = referenceDate.toLocaleString('de-DE', { month: 'long' });
    const currentYear = referenceDate.getFullYear();

    if (reportType === 'Monatlich') {
        periods.push({ value: `${currentMonthName} ${currentYear}`, label: `${currentMonthName} ${currentYear}` });
        const prevMonthDate = new Date(referenceDate);
        prevMonthDate.setMonth(referenceDate.getMonth() - 1);
        const prevMonthName = prevMonthDate.toLocaleString('de-DE', { month: 'long' });
        periods.push({ value: `${prevMonthName} ${prevMonthDate.getFullYear()}`, label: `${prevMonthName} ${prevMonthDate.getFullYear()}` });
    } else if (reportType === 'Jährlich') {
        periods.push({ value: String(currentYear), label: String(currentYear) });
        periods.push({ value: String(currentYear - 1), label: String(currentYear - 1) });
    } else {
        periods.push({ value: 'Gesamt', label: 'Gesamt' });
    }
    return periods;
};

const Reports: React.FC<ReportsProps> = ({ customers, transactions }) => {
  // Filter states
  const [reportType, setReportType] = useState('Monatlich');
  const [employee, setEmployee] = useState('Alle Mitarbeiter');
  const [transactionFilter, setTransactionFilter] = useState('Alle Transaktionen');

  const referenceDate = new Date();
  const initialPeriods = generateReportPeriods('Monatlich', referenceDate);
  const [timePeriod, setTimePeriod] = useState(initialPeriods.length > 0 ? initialPeriods[0].value : 'Gesamt');
  const [availableTimePeriods, setAvailableTimePeriods] = useState(initialPeriods);
