import React, { useState, useEffect } from 'react';
import { Routes, Route, useNavigate, Navigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import CustomerManagement from './pages/CustomerManagement';
import CustomerDetails from './pages/CustomerDetails';
import Reports from './pages/Reports';
import UserManagement from './pages/UserManagement';
import LoginPage from './pages/LoginPage';
import { Customer, Transaction, User, UserRoleEnum, Session } from './types';
import { supabase } from './supabaseClient';
import { TrainingLevelEnum } from './types';

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Check for initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
    });

    // Listen for auth state changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      if (session) {
        setLoading(true);
        // Fetch current user's profile
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single();

        if (profileError) {
          console.error('Error fetching user profile:', profileError);
          handleLogout(); // Log out if profile can't be fetched
          return;
        }

        if (profileData) {
          setCurrentUser(profileData);

          // Fetch data based on role
          if (profileData.role === UserRoleEnum.ADMIN || profileData.role === UserRoleEnum.MITARBEITER) {
            const { data: customersData } = await supabase.from('customers').select('*');
            const { data: transactionsData } = await supabase.from('transactions').select('*');
            setCustomers(customersData || []);
            setTransactions(transactionsData || []);

            if (profileData.role === UserRoleEnum.ADMIN) {
                const { data: usersData } = await supabase.from('profiles').select('*');
                setUsers(usersData || []);
            }
          } else if (profileData.role === UserRoleEnum.KUNDE && profileData.associatedCustomerId) {
            // Kunde only fetches their own data
            const { data: customerData } = await supabase.from('customers').select('*').eq('id', profileData.associatedCustomerId).single();
            const { data: transactionsData } = await supabase.from('transactions').select('*').eq('customerId', profileData.associatedCustomerId);
            setCustomers(customerData ? [customerData] : []);
            setTransactions(transactionsData || []);
          }
        }
        setLoading(false);
      } else {
        // No session, clear all data and stop loading
        setCurrentUser(null);
        setCustomers([]);
        setTransactions([]);
        setUsers([]);
        setLoading(false);
      }
    };
    fetchData();
  }, [session]);


  // --- AUTH HANDLERS ---
  const handleLogin = async (email: string, passwordInput: string): Promise<boolean> => {
    const { error } = await supabase.auth.signInWithPassword({ email, password: passwordInput });
    if (error) {
      console.error('Login error:', error.message);
      return false;
    }
    return true;
  };

  const handleRegister = async (email: string, password: string): Promise<boolean> => {
      const { data: authData, error: authError } = await supabase.auth.signUp({ email, password });
      if (authError || !authData.user) {
          alert("Fehler bei der Registrierung: " + (authError?.message || "Unbekannter Fehler."));
          return false;
      }

      const user = authData.user;
      const initials = (email.split('@')[0].substring(0, 2) || '??').toUpperCase();
      const customerId = crypto.randomUUID(); // FIX: Generate a standard UUID for the customer ID

      // Create a customer profile
      const { error: customerError } = await supabase.from('customers').insert({
          id: customerId,
          firstName: email.split('@')[0],
          lastName: '',
          email: user.email,
          balance: 0,
          level: TrainingLevelEnum.EINSTEIGER,
          createdAt: new Date().toISOString(),
          // Default values
          avatarInitials: initials,
          avatarColor: 'bg-blue-500',
          phone: '',
          dogName: 'Unbekannt',
          chipNumber: '',
          totalTransactions: 0,
          createdBy: 'System (Registrierung)',
          qrCodeData: `https://example.com/customer/${customerId}`,
          documents: [],
          trainingProgress: [
            { id: 1, name: TrainingLevelEnum.EINSTEIGER, requiredHours: 6, completedHours: 0, status: 'Aktuell' },
            { id: 2, name: TrainingLevelEnum.GRUNDLAGEN, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
            { id: 3, name: TrainingLevelEnum.FORTGESCHRITTENE, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
            { id: 4, name: TrainingLevelEnum.MASTERCLASS, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
            { id: 5, name: TrainingLevelEnum.EXPERT, requiredHours: 100, completedHours: 0, status: 'Gesperrt' },
          ]
      });
      if (customerError) {
          console.error("Fehler beim Erstellen des Kundenprofils: ", customerError);
          alert("Fehler beim Erstellen des Kundenprofils: " + customerError.message);
          // In a production app, you might want to delete the orphaned auth user here using an edge function.
          return false;
      }

      // Create the user profile in 'profiles' table
      const { error: profileError } = await supabase.from('profiles').insert({
          id: user.id, // Links to auth.users.id
          firstName: email.split('@')[0],
          lastName: '',
          email: user.email,
          role: UserRoleEnum.KUNDE,
          associatedCustomerId: customerId,
          avatarInitials: initials,
          avatarColor: 'bg-blue-500',
          createdAt: new Date().toISOString()
      });
      if (profileError) {
          console.error("Fehler beim Erstellen des Benutzerprofils: ", profileError);
          alert("Fehler beim Erstellen des Benutzerprofils: " + profileError.message);
          // In a production app, you'd also clean up the customer and auth user here.
          return false;
      }

      // Manually trigger a session refresh to fetch the new profile
      setSession(authData.session);
      return true;
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setSession(null);
    navigate('/login', { replace: true });
  };

  // --- DATA HANDLERS ---
  const handleUpdateCustomer = async (updatedCustomer: Customer) => {
    const { data, error } = await supabase
      .from('customers')
      .update(updatedCustomer)
      .eq('id', updatedCustomer.id)
      .select()
      .single();
    if (error) console.error('Error updating customer:', error);
    else if (data) {
      setCustomers(prev => prev.map(c => c.id === data.id ? data : c));
    }
  };

  const handleAddTransaction = async (newTransaction: Omit<Transaction, 'id'>) => {
    const { data, error } = await supabase
      .from('transactions')
      .insert(newTransaction)
      .select()
      .single();
    if (error) console.error('Error adding transaction:', error);
    else if (data) {
      setTransactions(prev => [...prev, data]);
    }
  };

  const handleAddUser = async (newUser: Omit<User, 'id' | 'createdAt'>) => {
      alert("Das Hinzufügen von Benutzern über die App ist in dieser Version nicht implementiert. Bitte verwenden Sie das Supabase Dashboard, um Benutzer einzuladen und ihnen eine Rolle in der 'profiles'-Tabelle zuzuweisen.");
      // This would require admin rights to create an auth user, which is insecure on the client.
      // The secure way is via the Supabase dashboard or a server-side edge function.
      // For now, this function is a placeholder.
  };

  const handleUpdateUser = async (updatedUser: User) => {
    const { id, ...updateData } = updatedUser;
    const { data, error } = await supabase
      .from('profiles')
      .update(updateData)
      .eq('id', id)
      .select()
      .single();
    if (error) console.error('Error updating user:', error);
    else if (data) {
        setUsers(prev => prev.map(u => u.id === data.id ? data : u));
    }
  };

  const handleDeleteUser = async (userId: string) => {
      alert("Das Löschen von Benutzern über die App ist in dieser Version nicht implementiert. Bitte verwenden Sie das Supabase Dashboard.");
      // Deleting a user requires deleting their profile AND their auth entry.
      // The latter is a protected operation and should be done via an edge function.
  };

  if (loading) {
    return <div className="flex items-center justify-center min-h-screen">Lade App...</div>;
  }

  // --- RENDER LOGIC ---
  const renderAppContent = () => {
    if (!session || !currentUser) {
      return (
        <Routes>
          <Route path="/login" element={<LoginPage onLogin={handleLogin} onRegister={handleRegister} />} />
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      );
    }

    return (
      <div className="flex min-h-screen bg-gray-100">
        <Sidebar appName="Mantrailing Card" currentUser={currentUser} onLogout={handleLogout} />
        <main className="flex-1 md:ml-64 p-0">
          <Routes>
            {currentUser.role === UserRoleEnum.ADMIN && (
              <>
                <Route path="/" element={<Dashboard customers={customers} transactions={transactions} />} />
                <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                <Route path="/reports" element={<Reports customers={customers} transactions={transactions} />} />
                <Route path="/users" element={<UserManagement users={users} onAddUser={handleAddUser} onUpdateUser={handleUpdateUser} onDeleteUser={handleDeleteUser} />} />
