-- Diese Funktion stellt die korrekte Reihenfolge sicher: 1. Kunde erstellen, 2. Profil erstellen.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  new_customer_id uuid;
BEGIN
  -- 1. Zuerst den 'customers'-Eintrag erstellen und dessen neue ID speichern.
  INSERT INTO public.customers (
    "firstName", "lastName", email, phone, "dogName", "chipNumber", balance, "totalTransactions", level, "createdBy", "qrCodeData", documents, "trainingProgress", "avatarInitials", "avatarColor"
  ) VALUES (
    'Neuer', 
    'Kunde', 
    NEW.email, 
    '', 
    '', 
    '', 
    0, 
    0, 
    'Einsteiger'::"TrainingLevelEnum", 
    'System', 
    'https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=' || NEW.id::text, 
    '[]'::jsonb,
    '[{"id":1,"name":"Einsteiger","status":"Aktuell","completedHours":0,"requiredHours":10},{"id":2,"name":"Grundlagen","status":"Gesperrt","completedHours":0,"requiredHours":20},{"id":3,"name":"Fortgeschrittene","status":"Gesperrt","completedHours":0,"requiredHours":30},{"id":4,"name":"Masterclass","status":"Gesperrt","completedHours":0,"requiredHours":40},{"id":5,"name":"Expert","status":"Gesperrt","completedHours":0,"requiredHours":500}]'::jsonb,
    'NK',
    'bg-gray-500'
  ) RETURNING id INTO new_customer_id;

  -- 2. Danach den 'profiles'-Eintrag erstellen und die neue Kunden-ID verwenden.
  INSERT INTO public.profiles (
    id, "firstName", "lastName", email, role, "associatedCustomerId", "avatarInitials", "avatarColor"
  ) VALUES (
    NEW.id, 
    'Neuer', 
    'Kunde', 
    NEW.email, 
    'Kunde'::"UserRoleEnum", 
    new_customer_id,
    'NK',
    'bg-gray-500'
  );

  RETURN NEW;
END;
$$;

