-- INSERT: Nur der interne Datenbankbenutzer (postgres) kann über den Trigger einfügen.
CREATE POLICY "Allow server-side profile creation." ON public.profiles
    FOR INSERT WITH CHECK (current_user = 'postgres');
-- SELECT: Benutzer können ihr eigenes Profil sehen. Mitarbeiter/Admins können alle sehen.
CREATE POLICY "Users can view their own profile." ON public.profiles
    FOR SELECT USING (auth.uid() = id);
CREATE POLICY "Admins and staff can view all profiles." ON public.profiles
    FOR SELECT USING (get_my_role() IN ('Admin', 'Mitarbeiter'));
-- UPDATE: Benutzer können ihr eigenes Profil aktualisieren. Admins können jedes aktualisieren.
CREATE POLICY "Users can update their own profile." ON public.profiles
    FOR UPDATE USING (auth.uid() = id);
CREATE POLICY "Admins can update any profile." ON public.profiles
    FOR UPDATE USING (get_my_role() = 'Admin');

-- === RICHTLINIEN FÜR 'customers' TABELLE ===
-- INSERT: Nur der interne Datenbankbenutzer (postgres) kann über den Trigger einfügen.
CREATE POLICY "Allow server-side customer creation." ON public.customers
    FOR INSERT WITH CHECK (current_user = 'postgres');
