    FOR UPDATE USING (id = (SELECT "associatedCustomerId" FROM public.profiles WHERE id = auth.uid()));
CREATE POLICY "Staff can update all customers." ON public.customers
    FOR UPDATE USING (get_my_role() IN ('Admin', 'Mitarbeiter'));
-- DELETE: Nur Mitarbeiter/Admins können löschen.
CREATE POLICY "Staff can delete customers." ON public.customers
    FOR DELETE USING (get_my_role() IN ('Admin', 'Mitarbeiter'));

