    FOR SELECT USING ("customerId" = (SELECT "associatedCustomerId" FROM public.profiles WHERE id = auth.uid()));
CREATE POLICY "Staff can view all transactions." ON public.transactions
    FOR SELECT USING (get_my_role() IN ('Admin', 'Mitarbeiter'));
-- UPDATE: Nur Mitarbeiter/Admins können Transaktionen aktualisieren.
CREATE POLICY "Staff can update transactions." ON public.transactions
    FOR UPDATE USING (get_my_role() IN ('Admin', 'Mitarbeiter'));
-- DELETE: Nur Mitarbeiter/Admins können Transaktionen löschen.
CREATE POLICY "Staff can delete transactions." ON public.transactions
    FOR DELETE USING (get_my_role() IN ('Admin', 'Mitarbeiter'));
