import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { USE_MOCK_DATA } from './config';

// WICHTIG: Ersetzen Sie diese Platzhalter durch Ihre tatsächlichen Supabase-Projekt-URL und den anon key.
// Diese finden Sie in Ihren Supabase-Projekteinstellungen unter "API".
const supabaseUrl = 'IHRE_SUPABASE_URL'; // z.B. 'https://xyz.supabase.co'
const supabaseAnonKey = 'IHR_SUPABASE_ANON_KEY'; // Ein langer String

let supabaseInstance: SupabaseClient | null = null;

/**
 * Erstellt und gibt eine Supabase-Client-Instanz zurück.
 * Die Instanz wird nur einmal erstellt (Singleton-Muster).
 * Gibt `null` zurück, wenn USE_MOCK_DATA true ist, um den App-Absturz zu verhindern.
 */
export const getSupabaseClient = (): SupabaseClient | null => {
  if (USE_MOCK_DATA) {
    return null; // Im Mock-Modus wird keine Verbindung aufgebaut.
  }

  if (supabaseInstance) {
    return supabaseInstance;
  }

  // Wichtige Prüfung, um den Absturz zu verhindern, falls die URL ungültig ist.
  if (!supabaseUrl.startsWith('http')) {
      console.error("Ungültige Supabase-URL. Bitte überprüfen Sie Ihre Konfiguration in supabaseClient.ts");
      // Der Fehler wird in der App.tsx-UI angezeigt, anstatt hier einen Absturz zu verursachen.
      throw new Error(`Invalid supabaseUrl: Must be a valid HTTP or HTTPS URL.`);
  }

  supabaseInstance = createClient(supabaseUrl, supabaseAnonKey);
  return supabaseInstance;
};

