      firstName, lastName, email, phone: '', dogName: '', chipNumber: '',
      balance: 0, totalTransactions: 0, level: TrainingLevelEnum.EINSTEIGER,
      // 'created_at' is removed. The database will set this automatically.
      createdBy: 'Registrierung', // This is crucial for the RLS policy
      qrCodeData: `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=https://example.com/customer/${associatedCustomerId}`,
      documents: [],
      trainingProgress: [
        { id: 1, name: TrainingLevelEnum.EINSTEIGER, requiredHours: 6, completedHours: 0, status: 'Aktuell' },
        { id: 2, name: TrainingLevelEnum.GRUNDLAGEN, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 3, name: TrainingLevelEnum.FORTGESCHRITTENE, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 4, name: TrainingLevelEnum.MASTERCLASS, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 5, name: TrainingLevelEnum.EXPERT, requiredHours: 100, completedHours: 0, status: 'Gesperrt' },
      ],
    };

    // STEP 2: Create the customer record BEFORE creating the user.
    const { error: customerInsertError } = await supabase.from('customers').insert([{
      ...newCustomer,
      trainingProgress: JSON.stringify(newCustomer.trainingProgress)
    }]);

    if (customerInsertError) {
      console.error("Customer Insert Error (Step 1):", customerInsertError);
      return `Fehler beim Erstellen des Kundenprofils: ${customerInsertError.message}`;
    }

    // STEP 3: Now that the customer exists, create the auth user.
    // The trigger will now find the customer and the foreign key constraint will be satisfied.
    const { error: signUpError } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          firstName,
          lastName,
          role: UserRoleEnum.KUNDE,
          associatedCustomerId // Pass the now-existing customer ID
        }
      }
    });

    if (signUpError) {
      console.error("Sign-Up Error (Step 2):", signUpError);
      // In a production app, you might want to delete the orphaned customer record created in step 2.
      // This requires admin privileges and is complex to handle from the client.
      return `Registrierungsfehler: ${signUpError.message}. Bitte kontaktieren Sie den Support.`;
    }

    // onAuthStateChange will handle the login and data refresh.
    return null;
  };


  const handleUpdateCustomer = async (updatedCustomer: Customer) => {
    if (!supabase) return;
    const { dataSource, ...customerToUpdate } = updatedCustomer;
    const { error } = await supabase.from('customers').update({
      ...customerToUpdate,
      trainingProgress: JSON.stringify(customerToUpdate.trainingProgress)
    }).eq('id', updatedCustomer.id);
    if (error) {
        alert(`Fehler beim Speichern der Kundendaten: ${error.message}`);
    } else {
        setCustomers(prev => prev.map(c => (c.id === updatedCustomer.id ? updatedCustomer : c)));
    }
  };

  const handleAddTransaction = async (newTransaction: Omit<Transaction, 'created_at'>) => {
    if (!supabase) return;
    const { error } = await supabase.from('transactions').insert([newTransaction]);
    if (error) {
        alert(`Fehler beim Buchen der Transaktion: ${error.message}`);
    } else {
        // To properly update state, we need a complete transaction object, including created_at
        // For simplicity, we'll refetch data or just add what we have.
        // A full solution would get the created transaction back from the DB.
        const completeTransaction = { ...newTransaction, created_at: new Date().toISOString() };
        setTransactions(prev => [...prev, completeTransaction]);
    }
  };

  const handleUpdateUser = async (updatedUser: User) => {
    if (!supabase) return;
    const { error } = await supabase.from('profiles').update({
      firstName: updatedUser.firstName,
      lastName: updatedUser.lastName,
      role: updatedUser.role,
    }).eq('id', updatedUser.id);
    if (error) {
      alert(`Fehler beim Aktualisieren des Benutzers: ${error.message}`);
    } else {
      setUsers(prev => prev.map(u => (u.id === updatedUser.id ? updatedUser : u)));
      if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(prev => prev ? {...prev, ...updatedUser} : null);
      }
    }
  };

  const handleAddUser = (newUser: User) => alert("Neue Mitarbeiter müssen direkt im Supabase Dashboard unter 'Authentication' angelegt und deren Rolle im 'Table Editor' unter 'profiles' zugewiesen werden.");
  const handleDeleteUser = (userId: string) => alert("Das Löschen von Mitarbeitern muss aus Sicherheitsgründen direkt im Supabase Dashboard erfolgen.");

  const handleLogout = async () => {
    if (!supabase) return;
    await supabase.auth.signOut();
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-100">
        <div className="text-center">
          <p className="text-xl font-semibold text-gray-700">Mantrailing Card wird geladen...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-gray-100">
      {session && currentUser ? (
        <>
          <Sidebar appName="Mantrailing Card" currentUser={currentUser} onLogout={handleLogout} />
          <main className="flex-1 md:ml-64 p-0">
            <Routes>
              {currentUser.role === UserRoleEnum.ADMIN ? (
                <>
                  <Route path="/" element={<Dashboard customers={customers} transactions={transactions} onSync={()=>{}} isSyncing={false} syncError={null} />} />
                  <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="/reports" element={<Reports customers={customers} transactions={transactions} />} />
                  <Route path="/users" element={<UserManagement users={users} onAddUser={handleAddUser} onUpdateUser={handleUpdateUser} onDeleteUser={handleDeleteUser} />} />
                  <Route path="*" element={<Navigate replace to="/" />} />
                </>
              ) : currentUser.role === UserRoleEnum.MITARBEITER ? (
                <>
                  <Route path="/" element={<Dashboard customers={customers} transactions={transactions} onSync={()=>{}} isSyncing={false} syncError={null} />} />
                  <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="*" element={<Navigate replace to="/" />} />
                </>
              ) : currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId ? (
                <>
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="*" element={<Navigate replace to={`/customers/${currentUser.associatedCustomerId}`} />} />
                </>
              ) : (
                <Route path="*" element={<Navigate replace to="/login" />} />
              )}
            </Routes>
          </main>
        </>
      ) : (
        <Routes>
          <Route path="/login" element={<LoginPage onLogin={handleLogin} onRegister={handleRegister} />} />
          <Route path="*" element={<Navigate replace to="/login" />} />
        </Routes>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import Card from '../components/Card';
import StatCard from '../components/StatCard';
import { REFERENCE_DATE } from '../constants'; // Only REFERENCE_DATE remains in constants
import Avatar from '../components/Avatar';
import { ArrowUpCircleIcon, ArrowDownCircleIcon, UsersIcon, DollarSignIcon, ClipboardIcon, RepeatIcon, HomeIcon } from '../components/Icons';
import { Link } from 'react-router-dom';
import { parseDateString, isSameDay, isSameMonth } from '../utils';
import { Customer, Transaction } from '../types'; // Import types
import Button from '../components/Button';

interface DashboardProps {
  customers: Customer[];
  transactions: Transaction[];
  onSync: () => void;
  isSyncing: boolean;
  syncError: string | null;
}

const Dashboard: React.FC<DashboardProps> = ({ customers, transactions, onSync, isSyncing, syncError }) => {
  // Dynamic calculations for Dashboard Stats
  const totalCustomers = customers.length;
  const totalBalance = customers.reduce((sum, customer) => sum + customer.balance, 0);

  const today = REFERENCE_DATE;
  const currentMonthTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    return transactionDate && isSameMonth(transactionDate, today);
  });
  const todayTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    return transactionDate && isSameDay(transactionDate, today);
  });

  const dashboardStats = [
    { title: 'Kunden Gesamt', value: totalCustomers, icon: UsersIcon, color: 'bg-green-100 text-green-700' },
    { title: 'Guthaben gesamt', value: totalBalance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }), icon: DollarSignIcon, color: 'bg-orange-100 text-orange-700' },
    { title: 'Transaktionen Heute', value: todayTransactions.length, icon: ClipboardIcon, color: 'bg-blue-100 text-blue-700' },
    { title: 'Transaktionen Monat', value: currentMonthTransactions.length, icon: RepeatIcon, color: 'bg-purple-100 text-purple-700' },
  ];

  // Aktuelle Kunden (based on created_at, max 5, scrollable)
  const recentCustomers = [...customers]
    .sort((a, b) => {
      const dateA = parseDateString(a.created_at);
      const dateB = parseDateString(b.created_at);
      if (!dateA || !dateB) return 0; // Handle invalid dates
      return dateB.getTime() - dateA.getTime(); // Sort descending
    })
    .slice(0, 5); // Take top 5

  // Letzte Transaktionen (max 5, scrollable)
  const latestTransactions = [...transactions]
    .sort((a, b) => {
      const dateA = parseDateString(a.date);
      const dateB = parseDateString(b.date);
      if (!dateA || !dateB) return 0; // Handle invalid dates
      return dateB.getTime() - dateA.getTime(); // Sort descending
    })
    .slice(0, 5); // Take top 5

  return (
    <div className="p-6 md:p-8 lg:p-10">
      <h1 className="text-3xl font-bold text-gray-900 mb-2">Willkommen, Christian Christian!</h1>
      <p className="text-gray-600 mb-8">Übersicht ihrer Trails-Wertkarten</p>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {dashboardStats.map((stat, index) => (
          <StatCard
            key={index}
            title={stat.title}
            value={stat.value}
            icon={stat.icon}
            color={stat.color}
          />
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          {/* Aktuelle Kunden */}
          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Aktuelle Kunden</h2>
            <div className="space-y-4 max-h-96 overflow-y-auto custom-scrollbar">
              {recentCustomers.length === 0 ? (
                <p className="text-gray-500 text-sm">Keine aktuellen Kunden gefunden.</p>
              ) : (
                recentCustomers.map((customer) => (
                  <Link to={`/customers/${customer.id}`} key={customer.id} className="flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 rounded-lg transition-colors duration-200">
                    <div className="flex items-center">
                      <Avatar initials={customer.avatarInitials} color={customer.avatarColor} size="md" className="mr-3" />
                      <div>
                        <p className="font-medium text-gray-900">{customer.firstName} {customer.lastName}</p>
                        <p className="text-sm text-gray-500">{customer.dogName}</p>
                      </div>
                    </div>
                    <p className="font-semibold text-gray-800">{customer.balance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}</p>
                  </Link>
                ))
              )}
            </div>
          </Card>

          {/* Letzte Transaktionen */}
          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Letzte Transaktionen</h2>
            <div className="space-y-4 max-h-96 overflow-y-auto custom-scrollbar">
              {latestTransactions.length === 0 ? (
                <p className="text-gray-500 text-sm">Keine aktuellen Transaktionen gefunden.</p>
              ) : (
                latestTransactions.map((transaction) => {
                  const customer = customers.find(c => c.id === transaction.customerId);
                  const isRecharge = transaction.type === 'recharge';
                  const TransactionIcon = isRecharge ? ArrowUpCircleIcon : ArrowDownCircleIcon;
                  const iconColor = isRecharge ? 'text-green-500' : 'text-red-500';
                  const amountColor = isRecharge ? 'text-green-700' : 'text-red-700';
                  const amountSign = isRecharge ? '+' : '-';

                  return (
                    <div key={transaction.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                      <div className="flex items-center">
                        <span className={`p-2 rounded-full bg-gray-200 mr-3 ${iconColor}`}>
                          <TransactionIcon className="h-5 w-5" />
                        </span>
                        <div>
                          <p className="font-medium text-gray-900">{customer?.firstName} {customer?.lastName}</p>
                          <p className="text-sm text-gray-500">{transaction.date} - {transaction.description}</p>
                        </div>
                      </div>
                      <p className={`font-semibold ${amountColor}`}>
                        {amountSign}{Math.abs(transaction.amount).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}
                      </p>
                    </div>
                  );
                })
              )}
            </div>
          </Card>
        </div>

        {/* NEUE SYNCHRONISIERUNGS-KARTE */}
        <div className="lg:col-span-1">
          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Datenbank-Synchronisierung</h2>
            <div className="space-y-4">
              <div className="p-3 bg-blue-50 text-blue-800 rounded-lg flex items-start">
                  <HomeIcon className="h-5 w-5 mr-3 mt-1 flex-shrink-0" />
                  <div>
                    <p className="font-semibold">Aktueller Status: Lokal</p>
                    <p className="text-sm">Die App verwendet aktuell die lokalen Demo-Daten.</p>
                  </div>
              </div>

              <Button 
                  variant="primary" 
                  className="w-full" 
                  onClick={onSync}
                  disabled={isSyncing}
              >
                  {isSyncing ? 'Synchronisiere...' : 'Daten von Supabase laden & mischen'}
              </Button>

              {syncError && (
                  <div className="p-3 bg-red-50 text-red-700 rounded-lg text-sm">
                      <p className="font-bold">Fehler bei der Synchronisierung:</p>
                      <p>{syncError}</p>
                  </div>
              )}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import Card from '../components/Card';
import StatCard from '../components/StatCard';
import Table, { Column } from '../components/Table';
import Button from '../components/Button';
import Avatar from '../components/Avatar';
import { PlusIcon, ChevronRightIcon, UsersIcon, HeartIcon, ClipboardIcon, RepeatIcon, UserPlusIcon } from '../components/Icons';
import { ALPHABET, REFERENCE_DATE } from '../constants'; // Only ALPHABET and REFERENCE_DATE remain in constants
import { Customer, CustomerTableData, TrainingLevelEnum, Transaction, User, UserRoleEnum } from '../types'; // Import types
import { useNavigate } from 'react-router-dom';
import { parseDateString, isSameMonth } from '../utils';

interface CustomerManagementProps {
  customers: Customer[];
  transactions: Transaction[];
  currentUser: User; // Added currentUser prop
}

// Helper function to get color classes based on training level for the badge
const getLevelColorClass = (level: TrainingLevelEnum) => {
  switch (level) {
    case TrainingLevelEnum.EINSTEIGER:
      return 'bg-fuchsia-100 text-fuchsia-800'; // Orchid
    case TrainingLevelEnum.GRUNDLAGEN:
      return 'bg-lime-100 text-lime-800'; // Lime Green
    case TrainingLevelEnum.FORTGESCHRITTENE:
      return 'bg-sky-100 text-sky-800'; // Sky Blue
    case TrainingLevelEnum.MASTERCLASS:
      return 'bg-amber-100 text-amber-800'; // Peru
    case TrainingLevelEnum.EXPERT:
      return 'bg-indigo-100 text-indigo-800'; // Indigo
    default:
      return 'bg-gray-100 text-gray-800'; // Default
  }
};

// Helper function to get color classes based on training level for the avatar circle
const getAvatarColorForLevel = (level: TrainingLevelEnum) => {
  switch (level) {
    case TrainingLevelEnum.EINSTEIGER:
      return 'bg-fuchsia-500'; // Orchid (500-level for stronger color on avatar)
    case TrainingLevelEnum.GRUNDLAGEN:
      return 'bg-lime-500'; // Lime Green
    case TrainingLevelEnum.FORTGESCHRITTENE:
      return 'bg-sky-500'; // Sky Blue
    case TrainingLevelEnum.MASTERCLASS:
      return 'bg-amber-500'; // Peru
    case TrainingLevelEnum.EXPERT:
      return 'bg-indigo-500'; // Indigo
    default:
      return 'bg-gray-400'; // Default (a neutral grey)
  }
};

const DatabaseIcon = () => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-blue-500 ml-2" viewBox="0 0 20 20" fill="currentColor">
    <path d="M3 12v3c0 1.657 3.134 3 7 3s7-1.343 7-3v-3c0 1.657-3.134 3-7 3s-7-1.343-7-3z" />
    <path d="M3 7v3c0 1.657 3.134 3 7 3s7-1.343 7-3V7c0 1.657-3.134 3-7 3S3 8.657 3 7z" />
    <path d="M17 5c0 1.657-3.134 3-7 3S3 6.657 3 5s3.134-3 7-3 7 1.343 7 3z" />
  </svg>
);


const CustomerManagement: React.FC<CustomerManagementProps> = ({ customers, transactions, currentUser }) => {
  const navigate = useNavigate();
  const [activeFilter, setActiveFilter] = useState<string>('Alle');

  const totalCustomers = customers.length;
  const totalBalance = customers.reduce((sum, c) => sum + c.balance, 0);

  const today = REFERENCE_DATE;
  const currentMonthTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    return transactionDate && isSameMonth(transactionDate, today);
  });
  const monthlyTransactionsCount = currentMonthTransactions.length;

  const activeCustomerIds = new Set(
    currentMonthTransactions.map(t => t.customerId)
  );
  const activeCustomersCount = customers.filter(c => activeCustomerIds.has(c.id)).length;

  const filteredCustomers = customers.filter((customer) => {
    if (activeFilter === 'Alle') return true;
    return customer.lastName.startsWith(activeFilter);
  });

  const customerTableData: CustomerTableData[] = filteredCustomers.map((customer) => ({
    id: customer.id,
    avatarInitials: customer.avatarInitials,
    avatarColor: customer.avatarColor,
    name: `${customer.firstName} ${customer.lastName}\n${customer.id}`,
    dog: customer.dogName,
    balance: customer.balance,
    level: customer.level,
    created_at: customer.created_at,
    dataSource: customer.dataSource, // Pass dataSource to table data
  }));

  const columns: Column<CustomerTableData>[] = [
    {
      key: 'name',
      header: 'Kunde',
      render: (item: CustomerTableData) => (
        <div className="flex items-center">
          <Avatar
            initials={item.avatarInitials}
            color={getAvatarColorForLevel(item.level)}
            size="md"
            className="mr-3"
          />
          <div>
            <div className="flex items-center">
                <p className="font-medium text-gray-900">{item.name.split('\n')[0]}</p>
                {item.dataSource === 'db' && <DatabaseIcon />}
            </div>
            <p className="text-sm text-gray-500">{item.name.split('\n')[1]}</p>
          </div>
        </div>
      ),
    },
    { key: 'dog', header: 'Hund' },
    {
      key: 'balance',
      header: 'Guthaben',
      render: (item: CustomerTableData) => item.balance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }),
    },
    {
      key: 'level',
      header: 'Level',
      render: (item: CustomerTableData) => (
        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getLevelColorClass(item.level)}`}>
          {item.level}
        </span>
      ),
    },
    { key: 'created_at', header: 'Erstellt' },
    {
      key: 'id',
      header: '',
      render: (item: CustomerTableData) => (
        <ChevronRightIcon className="h-5 w-5 text-gray-400" />
      ),
      className: 'text-right',
    },
  ];

  const handleRowClick = (customerData: CustomerTableData) => {
    navigate(`/customers/${customerData.id}`);
  };

  const canCreateCustomer = currentUser.role === UserRoleEnum.ADMIN || currentUser.role === UserRoleEnum.MITARBEITER;

  return (
    <div className="p-6 md:p-8 lg:p-10">
      <div className="flex justify-between items-center mb-2">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Kundenverwaltung</h1>
          <p className="text-gray-600">Verwalten Sie alle Ihre Kunden an einem Ort</p>
        </div>
        {canCreateCustomer && (
          <Button variant="success" icon={UserPlusIcon}>
            Neuer Kunde
          </Button>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 my-8">
        <StatCard
          title="Kunden Gesamt"
          value={totalCustomers}
          icon={UsersIcon}
          color="bg-green-100 text-green-700"
        />
        <StatCard
          title="Aktiv"
          value={activeCustomersCount}
          icon={HeartIcon}
          color="bg-orange-100 text-orange-700"
        />
        <StatCard
          title="Guthaben"
          value={totalBalance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}
          icon={ClipboardIcon}
          color="bg-blue-100 text-blue-700"
        />
        <StatCard
          title="Transaktionen Monat"
          value={monthlyTransactionsCount}
          icon={RepeatIcon}
          color="bg-purple-100 text-purple-700"
        />
      </div>

      <Card className="mb-6 px-4 py-2">
        <div className="flex flex-wrap justify-between gap-2">
          <button
            onClick={() => setActiveFilter('Alle')}
            className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors
              ${activeFilter === 'Alle' ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
          >
            Alle
          </button>
          {ALPHABET.map((letter) => (
            <button
              key={letter}
              onClick={() => setActiveFilter(letter)}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors
                ${activeFilter === letter ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </Card>

      <Card>
        <h2 className="text-xl font-semibold text-gray-900 mb-4">Kundenliste ({filteredCustomers.length})</h2>
        <Table data={customerTableData} columns={columns} onRowClick={handleRowClick} />
      </Card>
    </div>
  );
};

