interface CustomerDetailsProps {
  customers: Customer[];
  transactions: Transaction[];
  onUpdateCustomer: (updatedCustomer: Customer) => void;
  onAddTransaction: (newTransaction: Omit<Transaction, 'created_at'>) => void;
  currentUser: User;
}

const CustomerDetails: React.FC<CustomerDetailsProps> = ({
  customers,
  transactions,
  onUpdateCustomer,
  onAddTransaction,
  currentUser,
}) => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [showConfirmationModal, setShowConfirmationModal] = useState(false);
  const [showTransactionTypeModal, setShowTransactionTypeModal] = useState(false);
  const [isTransactionHistoryModalOpen, setIsTransactionHistoryModalOpen] = useState(false);
  const [transactionData, setTransactionData] = useState<TransactionConfirmationData | null>(null);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [isLoadingCustomer, setIsLoadingCustomer] = useState(true);
  const [isEditMode, setIsEditMode] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editableData, setEditableData] = useState({
    phone: '',
    dogName: '',
    chipNumber: '',
  });

  useEffect(() => {
    setIsLoadingCustomer(true);
    if (id) {
      const foundCustomer = customers.find((c) => c.id === id);
      setCustomer(foundCustomer || null);

      if (foundCustomer) {
        setEditableData({
          phone: foundCustomer.phone,
          dogName: foundCustomer.dogName,
          chipNumber: foundCustomer.chipNumber,
        });
      }
    } else {
      setCustomer(null);
    }
    setIsLoadingCustomer(false);
  }, [id, customers]);

  // Authorization Effect: Redirect if a customer tries to access another customer's page
  useEffect(() => {
    if (currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId && id !== currentUser.associatedCustomerId) {
        navigate(`/customers/${currentUser.associatedCustomerId}`, { replace: true });
    }
  }, [currentUser, id, navigate]);

  const [expandedSections, setExpandedSections] = useState<Record<number, boolean>>({});

  useEffect(() => {
    if (customer) {
      setExpandedSections(prev => {
        const newExpanded = { ...prev };
        customer.trainingProgress.forEach(section => {
          if (newExpanded[section.id] === undefined) {
            newExpanded[section.id] = false;
          }
        });
        return newExpanded;
      });
    }
  }, [customer]);

  // Filter and sort transactions for the current customer
  const customerTransactions = transactions
    .filter(t => t.customerId === id)
    .sort((a, b) => {
      const dateA = new Date(a.date.split('.').reverse().join('-'));
      const dateB = new Date(b.date.split('.').reverse().join('-'));
      return dateB.getTime() - dateA.getTime();
    });

  if (!id) {
    return (
      <div className="p-8 text-center text-red-600">
        Keine Kunden-ID in der URL gefunden.
        <Button variant="primary" onClick={() => navigate('/customers')} className="mt-4">
          Zurück zur Kundenliste
        </Button>
      </div>
    );
  }

  if (isLoadingCustomer) {
    return <div className="p-8 text-center text-gray-600">Lade Kundendaten...</div>;
  }

  if (!customer) {
    return (
      <div className="p-8 text-center text-gray-600">
        Kunde mit ID "{id}" nicht gefunden.
        <Button variant="primary" onClick={() => navigate('/customers')} className="mt-4">
          Zurück zur Kundenliste
        </Button>
      </div>
    );
  }

  const handleOpenConfirmationModal = (amount: number, type: 'Aufladung' | 'Abbuchung', description?: string) => {
    const oldBalance = customer.balance;
    const newBalance = type === 'Aufladung' ? oldBalance + amount : oldBalance - amount;
    setTransactionData({
      customerId: customer.id,
      customerName: `${customer.firstName} ${customer.lastName}`,
      employee: CURRENT_EMPLOYEE,
      transactionType: type,
      amount: amount,
      oldBalance: oldBalance,
      newBalance: newBalance,
      description: description,
    });
    setShowConfirmationModal(true);
  };

  const handleConfirmTransaction = () => {
    if (!transactionData || !customer) return;

    let finalUpdatedCustomer: Customer = { ...customer };
    finalUpdatedCustomer.balance = transactionData.newBalance;
    finalUpdatedCustomer.totalTransactions = customer.totalTransactions + 1;

    const isRecharge = transactionData.transactionType === 'Aufladung';
    if (!isRecharge && transactionData.description === 'Trails' && transactionData.amount === 18) {
      const currentTrainingProgress = [...customer.trainingProgress];
      let customerOverallLevel = finalUpdatedCustomer.level;
      const currentLevelIndex = currentTrainingProgress.findIndex(s => s.status === 'Aktuell');

      if (currentLevelIndex !== -1) {
        const currentSection = { ...currentTrainingProgress[currentLevelIndex] };
        if (currentSection.name === TrainingLevelEnum.EXPERT) {
          if (currentSection.completedHours < 500) {
            currentSection.completedHours += 1;
            currentTrainingProgress[currentLevelIndex] = currentSection;
          }
        } else if (currentSection.completedHours < currentSection.requiredHours) {
          currentSection.completedHours += 1;
          if (currentSection.completedHours === currentSection.requiredHours) {
            currentSection.status = 'Abgeschlossen';
            const nextLevelIndex = currentLevelIndex + 1;
            if (nextLevelIndex < currentTrainingProgress.length) {
              const nextSection = { ...currentTrainingProgress[nextLevelIndex] };
              nextSection.status = 'Aktuell';
              customerOverallLevel = nextSection.name;
              currentTrainingProgress[nextLevelIndex] = nextSection;
            }
          }
          currentTrainingProgress[currentLevelIndex] = currentSection;
        }
        finalUpdatedCustomer.trainingProgress = currentTrainingProgress;
        finalUpdatedCustomer.level = customerOverallLevel;
      }
    }

    onUpdateCustomer(finalUpdatedCustomer);

    const newTransaction: Omit<Transaction, 'created_at'> = {
      id: `trx-${transactions.length + 1}-${Date.now()}`,
      customerId: customer.id,
      type: transactionData.transactionType === 'Aufladung' ? 'recharge' : 'debit',
      description: transactionData.description || (transactionData.transactionType === 'Aufladung' ? 'Aufladung' : 'Trails'),
      amount: transactionData.amount,
      date: REFERENCE_DATE.toLocaleDateString('de-DE'),
      employee: CURRENT_EMPLOYEE,
    };
    onAddTransaction(newTransaction);
    setShowConfirmationModal(false);
    setTransactionData(null);
  };

  const handleSelectTransactionType = (type: 'Aufladung' | 'Abbuchung') => {
    setShowTransactionTypeModal(false);
    let defaultAmount = type === 'Aufladung' ? 215 : 18;
    let description = type === 'Aufladung' ? 'Guthabenaufladung' : 'Trails';
    handleOpenConfirmationModal(defaultAmount, type, description);
  };

  const handleToggleEditMode = () => {
    if (!isEditMode) {
      setEditableData({
        phone: customer.phone,
        dogName: customer.dogName,
        chipNumber: customer.chipNumber,
      });
    }
    setIsEditMode(!isEditMode);
  };

  const handleCancelEdit = () => {
    setIsEditMode(false);
  };

  const handleSaveChanges = () => {
    const updatedCustomer = {
      ...customer,
      phone: editableData.phone,
      dogName: editableData.dogName,
      chipNumber: editableData.chipNumber,
    };
    onUpdateCustomer(updatedCustomer);
    setIsEditMode(false);
  };

  const handleUpdateStammdaten = (data: NewCustomerData) => {
    if (!customer) return;
    const updatedCustomer = { ...customer, ...data };
    onUpdateCustomer(updatedCustomer);
    setIsEditModalOpen(false);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { id, value } = e.target;
    setEditableData(prev => ({ ...prev, [id]: value }));
  };

  const getStatusClasses = (status: string) => {
    switch (status) {
      case 'Aktuell': return 'bg-green-100 text-green-800';
      case 'Gesperrt': return 'bg-red-100 text-red-800';
      case 'Abgeschlossen': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const DataRow: React.FC<{ Icon: React.ElementType; label: string; value: string | number }> = ({ Icon, label, value }) => (
    <div>
      <div className="flex items-center text-gray-500 mb-1">
        <Icon className="h-4 w-4 mr-2" />
        <span className="text-sm font-medium">{label}</span>
      </div>
      <p className="font-semibold text-gray-900 ml-6">{value}</p>
    </div>
  );

  const toggleSection = (sectionId: number) => {
    setExpandedSections(prev => ({ ...prev, [sectionId]: !prev[sectionId] }));
  };

  const getLevelSummaryCardColors = (level: TrainingLevelEnum) => {
    switch (level) {
      case TrainingLevelEnum.EINSTEIGER: return { bg: 'bg-fuchsia-50', text: 'text-fuchsia-700', icon: 'text-fuchsia-700' };
      case TrainingLevelEnum.GRUNDLAGEN: return { bg: 'bg-lime-50', text: 'text-lime-700', icon: 'text-lime-700' };
      case TrainingLevelEnum.FORTGESCHRITTENE: return { bg: 'bg-sky-50', text: 'text-sky-700', icon: 'text-sky-700' };
      case TrainingLevelEnum.MASTERCLASS: return { bg: 'bg-amber-50', text: 'text-amber-700', icon: 'text-amber-700' };
      case TrainingLevelEnum.EXPERT: return { bg: 'bg-indigo-50', text: 'text-indigo-700', icon: 'text-indigo-700' };
      default: return { bg: 'bg-gray-50', text: 'text-gray-700', icon: 'text-gray-700' };
    }
  };

  const levelSummaryColors = getLevelSummaryCardColors(customer.level);
  const canPerformActions = currentUser.role === UserRoleEnum.ADMIN || currentUser.role === UserRoleEnum.MITARBEITER;
  const isCustomerViewing = currentUser.role === UserRoleEnum.KUNDE;

  return (
    <div className="p-6 md:p-8 lg:p-10 min-h-screen">
      <div className="flex items-center justify-between mb-6 flex-wrap gap-4">
        <div className="flex items-center">
          {!isCustomerViewing && (
            <button onClick={() => navigate('/customers')} className="text-gray-500 hover:text-gray-700 mr-4">
              <ArrowLeftIcon className="h-6 w-6" />
            </button>
          )}
          <h1 className="text-2xl font-bold text-gray-900 flex items-center">
            {customer.firstName} {customer.lastName}
            <span className="text-gray-500 font-normal text-base ml-2">
              {isCustomerViewing ? "Meine Übersicht" : "Kundendetails & Übersicht"}
            </span>
          </h1>
        </div>

        {isEditMode ? (
          <div className="flex space-x-3">
            <Button variant="outline" onClick={handleCancelEdit}>Abbrechen</Button>
            <Button variant="success" icon={SaveIcon} onClick={handleSaveChanges}>Speichern</Button>
          </div>
        ) : (
          <div className="flex space-x-3">
            {canPerformActions && (
              <>
                <Button variant="outline" onClick={() => setIsEditModalOpen(true)}>Stammdaten</Button>
                <Button variant="success" onClick={() => setShowTransactionTypeModal(true)}>Transaktionen</Button>
              </>
            )}
            {isCustomerViewing && (
              <Button variant="primary" icon={EditIcon} onClick={handleToggleEditMode}>Meine Daten bearbeiten</Button>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Persönliche Daten</h2>
            <div className="flex items-start">
              <Avatar initials={customer.avatarInitials} color={customer.avatarColor} size="lg" className="mr-6 flex-shrink-0" />
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-12 gap-y-6 flex-grow">
                <DataRow Icon={UserIcon} label="Vorname" value={customer.firstName} />
                <DataRow Icon={UserIcon} label="Nachname" value={customer.lastName} />
                <DataRow Icon={MailIcon} label="E-Mail" value={customer.email} />
                {isEditMode ? (
                  <Input id="phone" label="Telefon" value={editableData.phone} onChange={handleInputChange} />
                ) : (
                  <DataRow Icon={PhoneIcon} label="Telefon" value={customer.phone} />
                )}
                {isEditMode ? (
                  <Input id="dogName" label="Hund" value={editableData.dogName} onChange={handleInputChange} />
                ) : (
                  <DataRow Icon={HeartIcon} label="Hund" value={customer.dogName} />
                )}
                {isEditMode ? (
                  <Input id="chipNumber" label="Chipnummer" value={editableData.chipNumber} onChange={handleInputChange} />
                ) : (
                  <DataRow Icon={CreditCardIcon} label="Chipnummer" value={customer.chipNumber} />
                )}
              </div>
            </div>
          </Card>

          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Übersicht</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-green-50 p-4 rounded-lg flex flex-col justify-center items-center text-center">
                <p className="text-sm text-gray-600 mb-1">Aktuelles Guthaben</p>
                <p className="text-2xl font-bold text-green-700">{customer.balance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}</p>
              </div>
              <button
                onClick={() => setIsTransactionHistoryModalOpen(true)}
                className="bg-blue-50 p-4 rounded-lg flex flex-col justify-center items-center text-center w-full hover:bg-blue-100 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition-colors"
              >
                <p className="text-sm text-gray-600 mb-1">Transaktionen gesamt</p>
                <p className="text-2xl font-bold text-blue-700">{customer.totalTransactions}</p>
              </button>
              <div className={`${levelSummaryColors.bg} p-4 rounded-lg flex flex-col justify-center items-center text-center`}>
                <p className="text-sm text-gray-600 mb-1">Level</p>
                <div className="flex items-center mt-2">
                  <AwardIcon className={`h-10 w-10 mr-2 ${levelSummaryColors.icon}`} />
                  <p className={`text-2xl font-bold ${levelSummaryColors.text}`}>{customer.level}</p>
                </div>
              </div>
            </div>
          </Card>

          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Ausbildungsfortschritt</h2>
            <div className="space-y-6">
              {customer.trainingProgress.map((section) => {
                let headerBgClass = 'bg-gray-50';
                let levelCircleBgClass = 'bg-gray-400';

                switch (section.name) {
                  case TrainingLevelEnum.EINSTEIGER: headerBgClass = 'bg-fuchsia-50'; break;
                  case TrainingLevelEnum.GRUNDLAGEN: headerBgClass = 'bg-lime-50'; break;
                  case TrainingLevelEnum.FORTGESCHRITTENE: headerBgClass = 'bg-sky-50'; break;
                  case TrainingLevelEnum.MASTERCLASS: headerBgClass = 'bg-amber-50'; break;
                  case TrainingLevelEnum.EXPERT: headerBgClass = 'bg-indigo-50'; break;
                }
                switch (section.name) {
                  case TrainingLevelEnum.EINSTEIGER: levelCircleBgClass = 'bg-fuchsia-500'; break;
                  case TrainingLevelEnum.GRUNDLAGEN: levelCircleBgClass = 'bg-lime-500'; break;
                  case TrainingLevelEnum.FORTGESCHRITTENE: levelCircleBgClass = 'bg-sky-500'; break;
                  case TrainingLevelEnum.MASTERCLASS: levelCircleBgClass = 'bg-amber-500'; break;
                  case TrainingLevelEnum.EXPERT: levelCircleBgClass = 'bg-indigo-500'; break;
                }

                const isExpanded = expandedSections[section.id];
                return (
                  <div key={section.id} className="rounded-lg overflow-hidden border border-gray-200 shadow-sm">
                    <button
                      className={`p-4 flex items-center justify-between w-full text-left ${headerBgClass}`}
                      onClick={() => toggleSection(section.id)}
                      aria-expanded={isExpanded}
                      aria-controls={`section-content-${section.id}`}
                    >
                      <h3 className="text-lg font-medium text-gray-900 flex items-center">
                        <span className={`flex items-center justify-center h-8 w-8 rounded-full text-white font-bold text-base mr-3 ${levelCircleBgClass}`}>{section.id}</span>
                        {section.name}
                      </h3>
                      <div className="flex items-center">
                        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${getStatusClasses(section.status)} mr-2`}>{section.status}</span>
                        <ChevronDownIcon className={`h-5 w-5 text-gray-500 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
                      </div>
                    </button>
                    <div id={`section-content-${section.id}`} className={`${isExpanded ? 'block' : 'hidden'} p-4 bg-white border-t border-gray-200`}>
                      {section.name === TrainingLevelEnum.EXPERT ? (
                        (() => {
                          const currentHours = section.completedHours;
                          const fullMilestones = Math.floor(currentHours / 100);
                          const remainingHours = currentHours % 100;
                          return (
                            <>
                              <p className="text-sm text-gray-600 mb-3">Fortschritt: {currentHours} Trails absolviert im Expert-Status</p>
                              <div className="flex flex-wrap gap-2">
                                {Array.from({ length: fullMilestones }).map((_, i) => (<HundredHourMilestoneBadge key={`milestone-${i}`} milestoneNumber={i + 1} />))}
                                {Array.from({ length: remainingHours }).map((_, i) => (<TrainingPawIcon key={`paw-${i}`} filled={true} />))}
                              </div>
                            </>
                          );
                        })()
                      ) : (
                        <>
                          <p className="text-sm text-gray-600 mb-3">Fortschritt: {section.completedHours} / {section.requiredHours} Trails</p>
                          <div className="flex flex-wrap gap-2">
                            {Array.from({ length: section.completedHours }).map((_, i) => (<TrainingPawIcon key={i} filled={true} />))}
                            {Array.from({ length: section.requiredHours - section.completedHours }).map((_, i) => (<TrainingPawIcon key={`empty-${i}`} filled={false} />))}
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </Card>
        </div>
        <div className="lg:col-span-1 space-y-6">
          <Card>
            <h2 className="text-xl font-semibold text-gray-900 mb-4">Konto</h2>
            <div className="space-y-2 text-gray-700">
              <div className="flex justify-between"><span>Erstellt am</span><span className="font-bold">{customer.created_at}</span></div>
              <div className="flex justify-between"><span>Kunden-ID</span><span className="font-bold">{customer.id}</span></div>
            </div>
          </Card>

          <Card className="text-center">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">QR-Code</h2>
            <QRCodeDisplay dataUrl={customer.qrCodeData} className="mb-3" />
            <p className="text-sm text-gray-600">Scannen, um diese Kundenkarte schnell aufzurufen.</p>
          </Card>
        </div>
      </div>
      <TransactionConfirmationModal
        isOpen={showConfirmationModal}
        onClose={() => setShowConfirmationModal(false)}
        onConfirm={handleConfirmTransaction}
        data={transactionData}
      />
      <TransactionTypeSelectionModal
        isOpen={showTransactionTypeModal}
        onClose={() => setShowTransactionTypeModal(false)}
        onSelectType={handleSelectTransactionType}
      />
      <CustomerFormModal
        isOpen={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        onSubmit={handleUpdateStammdaten}
        customerToEdit={customer}
      />
      <TransactionHistoryModal
        isOpen={isTransactionHistoryModalOpen}
        onClose={() => setIsTransactionHistoryModalOpen(false)}
        transactions={customerTransactions}
        customerName={`${customer.firstName} ${customer.lastName}`}
      />
    </div>
  );
};

export default CustomerDetails;

import React from 'react';
import Card from '../components/Card';
import StatCard from '../components/StatCard';
import { REFERENCE_DATE } from '../constants'; // Only REFERENCE_DATE remains in constants
import Avatar from '../components/Avatar';
import { ArrowUpCircleIcon, ArrowDownCircleIcon, UsersIcon, DollarSignIcon, ClipboardIcon, RepeatIcon } from '../components/Icons';
import { Link } from 'react-router-dom';
import { parseDateString, isSameDay, isSameMonth } from '../utils';
import { Customer, Transaction } from '../types'; // Import types

interface DashboardProps {
  customers: Customer[];
  transactions: Transaction[];
}

const Dashboard: React.FC<DashboardProps> = ({ customers, transactions }) => {
  // Dynamic calculations for Dashboard Stats
  const totalCustomers = customers.length;
  const totalBalance = customers.reduce((sum, customer) => sum + customer.balance, 0);

  const today = REFERENCE_DATE;
  const currentMonthTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    return transactionDate && isSameMonth(transactionDate, today);
  });
  const todayTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    return transactionDate && isSameDay(transactionDate, today);
  });

  const dashboardStats = [
    { title: 'Kunden Gesamt', value: totalCustomers, icon: UsersIcon, color: 'bg-green-100 text-green-700' },
    { title: 'Guthaben gesamt', value: totalBalance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }), icon: DollarSignIcon, color: 'bg-orange-100 text-orange-700' },
    { title: 'Transaktionen Heute', value: todayTransactions.length, icon: ClipboardIcon, color: 'bg-blue-100 text-blue-700' },
    { title: 'Transaktionen Monat', value: currentMonthTransactions.length, icon: RepeatIcon, color: 'bg-purple-100 text-purple-700' },
  ];

  // Aktuelle Kunden (based on created_at, max 5, scrollable)
  const recentCustomers = [...customers]
    .sort((a, b) => {
      const dateA = parseDateString(a.created_at);
      const dateB = parseDateString(b.created_at);
      if (!dateA || !dateB) return 0; // Handle invalid dates
      return dateB.getTime() - dateA.getTime(); // Sort descending
    })
    .slice(0, 5); // Take top 5

  // Letzte Transaktionen (max 5, scrollable)
  const latestTransactions = [...transactions]
    .sort((a, b) => {
      const dateA = parseDateString(a.date);
      const dateB = parseDateString(b.date);
      if (!dateA || !dateB) return 0; // Handle invalid dates
      return dateB.getTime() - dateA.getTime(); // Sort descending
    })
    .slice(0, 5); // Take top 5

  return (
    <div className="p-6 md:p-8 lg:p-10">
      <h1 className="text-3xl font-bold text-gray-900 mb-2">Willkommen, Christian Christian!</h1>
      <p className="text-gray-600 mb-8">Übersicht ihrer Trails-Wertkarten</p>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {dashboardStats.map((stat, index) => (
          <StatCard
            key={index}
            title={stat.title}
            value={stat.value}
            icon={stat.icon}
            color={stat.color}
          />
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Aktuelle Kunden */}
        <Card>
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Aktuelle Kunden</h2>
          <div className="space-y-4 max-h-96 overflow-y-auto custom-scrollbar">
            {recentCustomers.length === 0 ? (
              <p className="text-gray-500 text-sm">Keine aktuellen Kunden gefunden.</p>
            ) : (
              recentCustomers.map((customer) => (
                <Link to={`/customers/${customer.id}`} key={customer.id} className="flex items-center justify-between p-3 bg-gray-50 hover:bg-gray-100 rounded-lg transition-colors duration-200">
                  <div className="flex items-center">
                    <Avatar initials={customer.avatarInitials} color={customer.avatarColor} size="md" className="mr-3" />
                    <div>
                      <p className="font-medium text-gray-900">{customer.firstName} {customer.lastName}</p>
                      <p className="text-sm text-gray-500">{customer.dogName}</p>
                    </div>
                  </div>
                  <p className="font-semibold text-gray-800">{customer.balance.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}</p>
                </Link>
              ))
            )}
          </div>
        </Card>

        {/* Letzte Transaktionen */}
        <Card>
          <h2 className="text-xl font-semibold text-gray-900 mb-4">Letzte Transaktionen</h2>
          <div className="space-y-4 max-h-96 overflow-y-auto custom-scrollbar">
            {latestTransactions.length === 0 ? (
              <p className="text-gray-500 text-sm">Keine aktuellen Transaktionen gefunden.</p>
            ) : (
              latestTransactions.map((transaction) => {
                const customer = customers.find(c => c.id === transaction.customerId);
                const isRecharge = transaction.type === 'recharge';
                const TransactionIcon = isRecharge ? ArrowUpCircleIcon : ArrowDownCircleIcon;
                const iconColor = isRecharge ? 'text-green-500' : 'text-red-500';
                const amountColor = isRecharge ? 'text-green-700' : 'text-red-700';
                const amountSign = isRecharge ? '+' : '-';

                return (
                  <div key={transaction.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                    <div className="flex items-center">
                      <span className={`p-2 rounded-full bg-gray-200 mr-3 ${iconColor}`}>
                        <TransactionIcon className="h-5 w-5" />
                      </span>
                      <div>
                        <p className="font-medium text-gray-900">{customer?.firstName} {customer?.lastName}</p>
                        <p className="text-sm text-gray-500">{transaction.date} - {transaction.description}</p>
                      </div>
                    </div>
                    <p className={`font-semibold ${amountColor}`}>
                      {amountSign}{Math.abs(transaction.amount).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}
                    </p>
                  </div>
                );
              })
            )}
          </div>
        </Card>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Routes, Route, useNavigate, Navigate } from 'react-router-dom';
import type { Session } from '@supabase/supabase-js';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import CustomerManagement from './pages/CustomerManagement';
import CustomerDetails from './pages/CustomerDetails';
import Reports from './pages/Reports';
import UserManagement from './pages/UserManagement';
import LoginPage from './pages/LoginPage';
import { Customer, Transaction, TrainingLevelEnum, User, UserRoleEnum } from './types';
import { REFERENCE_DATE } from './constants';
import { USE_MOCK_DATA } from './config';
import { getSupabaseClient } from './supabaseClient';

// Helper function to safely parse customer data from Supabase
const parseCustomerData = (c: any): Customer => {
  let trainingProgress = c.trainingProgress;
  // Supabase returns JSONB columns as strings, so we need to parse them.
  if (typeof trainingProgress === 'string') {
    try {
      trainingProgress = JSON.parse(trainingProgress);
    } catch (e) {
      console.error("Fehler beim Parsen von trainingProgress für Kunde:", c.id, e);
      trainingProgress = []; // Fallback auf ein leeres Array bei einem Fehler
    }
  }
  return { ...c, trainingProgress, dataSource: 'db' };
};


const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [users, setUsers] = useState<User[]>([]); // For UserManagement page (staff)
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  const navigate = useNavigate();
  const supabase = getSupabaseClient();

  // Effect 1: Manages the session from Supabase auth. This is the single source of truth for auth state.
  useEffect(() => {
    if (!supabase || USE_MOCK_DATA) {
      setIsLoading(false);
      navigate('/login');
      return;
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, [supabase, navigate]);

  // Effect 2: Fetches data when the session changes. This separates data logic from auth logic.
  useEffect(() => {
    if (!supabase) return;

    const fetchInitialData = async (currentSession: Session) => {
      setIsLoading(true);

      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', currentSession.user.id)
        .single();

      if (profileError) {
        console.error("Error fetching user profile:", profileError);
        await supabase.auth.signOut();
        setIsLoading(false);
        return;
      }

      const loggedInUser: User = {
        id: profileData.id,
        firstName: profileData.firstName || '',
        lastName: profileData.lastName || '',
        email: profileData.email,
        role: profileData.role as UserRoleEnum,
        associatedCustomerId: profileData.associatedCustomerId,
        avatarInitials: `${(profileData.firstName || '?').charAt(0)}${(profileData.lastName || '?').charAt(0)}`.toUpperCase(),
        avatarColor: 'bg-gray-500',
        created_at: new Date(profileData.created_at || Date.now()).toLocaleDateString('de-DE'),
      };
      setCurrentUser(loggedInUser);

      if (loggedInUser.role !== UserRoleEnum.KUNDE) {
        const { data: customersData, error: customersError } = await supabase.from('customers').select('*');
        if (customersError) console.error("Error fetching customers:", customersError.message);

        const { data: transactionsData, error: transactionsError } = await supabase.from('transactions').select('*');
        if (transactionsError) console.error("Error fetching transactions:", transactionsError.message);

        setCustomers(customersData?.map(parseCustomerData) || []);
        setTransactions(transactionsData || []);

        if (loggedInUser.role === UserRoleEnum.ADMIN) {
          const { data: staffData, error: staffError } = await supabase.from('profiles').select('*').in('role', ['Admin', 'Mitarbeiter']);
           if (staffError) console.error("Error fetching staff:", staffError.message);
          setUsers(staffData?.map(p => ({
            id: p.id,
            firstName: p.firstName || '', lastName: p.lastName || '', email: p.email, role: p.role,
            associatedCustomerId: p.associatedCustomerId,
            avatarInitials: `${(p.firstName || '?').charAt(0)}${(p.lastName || '?').charAt(0)}`.toUpperCase(),
            avatarColor: 'bg-gray-500',
            created_at: new Date(p.created_at || Date.now()).toLocaleDateString('de-DE'),
          })) || []);
        }
      } else if (loggedInUser.associatedCustomerId) {
        const { data: customerData } = await supabase.from('customers').select('*').eq('id', loggedInUser.associatedCustomerId).single();
        const { data: customerTransactions } = await supabase.from('transactions').select('*').eq('customerId', loggedInUser.associatedCustomerId);
        setCustomers(customerData ? [parseCustomerData(customerData)] : []);
        setTransactions(customerTransactions || []);
      }
      setIsLoading(false);
    };

    if (session) {
      fetchInitialData(session);
    } else {
      // Clear all data on logout
      setCurrentUser(null);
      setCustomers([]);
      setTransactions([]);
      setUsers([]);
      setIsLoading(false);
      navigate('/login');
    }
  }, [session, supabase, navigate]);

  // Effect 3: Handles navigation for logged-in customers.
  useEffect(() => {
    if (!isLoading && session && currentUser) {
        if (currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId) {
            const expectedPath = `/customers/${currentUser.associatedCustomerId}`;
            if (window.location.hash !== `#${expectedPath}`) {
                navigate(expectedPath, { replace: true });
            }
        }
    }
  }, [isLoading, session, currentUser, navigate]);

  const handleLogin = async (email: string, passwordInput: string): Promise<string | null> => {
    if (!supabase) return "Supabase Client nicht initialisiert.";
    const { error } = await supabase.auth.signInWithPassword({ email, password: passwordInput });
    if (error) {
        console.error("Login Error:", error);
        return error.message;
    }
    return null;
  };

  const handleRegister = async (email: string, password: string): Promise<string | null> => {
    if (!supabase) return "Supabase Client nicht initialisiert.";

    // STEP 1: Define all customer data first.
    const now = new Date();
    const associatedCustomerId = `cust-reg-${now.getTime()}`;
    const firstName = email.split('@')[0] || 'Neuer';
    const lastName = '(Kunde)';
    const initials = (firstName.substring(0, 2) || '??').toUpperCase();
    const avatarColors = ['bg-red-500', 'bg-orange-500', 'bg-purple-500', 'bg-indigo-500', 'bg-blue-500', 'bg-green-500', 'bg-teal-500', 'bg-fuchsia-500', 'bg-lime-500'];

    const newCustomer = {
      id: associatedCustomerId,
      avatarInitials: initials,
      avatarColor: avatarColors[Math.floor(Math.random() * avatarColors.length)],
      firstName, lastName, email, phone: '', dogName: '', chipNumber: '',
      balance: 0, totalTransactions: 0, level: TrainingLevelEnum.EINSTEIGER,
      // 'created_at' is removed. The database will set this automatically.
      createdBy: 'Registrierung', // This is crucial for the RLS policy
      qrCodeData: `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=https://example.com/customer/${associatedCustomerId}`,
      documents: [],
      trainingProgress: [
        { id: 1, name: TrainingLevelEnum.EINSTEIGER, requiredHours: 6, completedHours: 0, status: 'Aktuell' },
        { id: 2, name: TrainingLevelEnum.GRUNDLAGEN, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 3, name: TrainingLevelEnum.FORTGESCHRITTENE, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 4, name: TrainingLevelEnum.MASTERCLASS, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 5, name: TrainingLevelEnum.EXPERT, requiredHours: 100, completedHours: 0, status: 'Gesperrt' },
      ],
    };

    // STEP 2: Create the customer record BEFORE creating the user.
    const { error: customerInsertError } = await supabase.from('customers').insert([{
      ...newCustomer,
      trainingProgress: JSON.stringify(newCustomer.trainingProgress)
    }]);

    if (customerInsertError) {
      console.error("Customer Insert Error (Step 1):", customerInsertError);
      return `Fehler beim Erstellen des Kundenprofils: ${customerInsertError.message}`;
    }

    // STEP 3: Now that the customer exists, create the auth user.
    // The trigger will now find the customer and the foreign key constraint will be satisfied.
    const { error: signUpError } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          firstName,
          lastName,
          role: UserRoleEnum.KUNDE,
          associatedCustomerId // Pass the now-existing customer ID
        }
      }
    });

    if (signUpError) {
      console.error("Sign-Up Error (Step 2):", signUpError);
      // In a production app, you might want to delete the orphaned customer record created in step 2.
      // This requires admin privileges and is complex to handle from the client.
      return `Registrierungsfehler: ${signUpError.message}. Bitte kontaktieren Sie den Support.`;
    }

    // onAuthStateChange will handle the login and data refresh.
    return null;
  };


  const handleUpdateCustomer = async (updatedCustomer: Customer) => {
    if (!supabase) return;
    const { dataSource, ...customerToUpdate } = updatedCustomer;
    const { error } = await supabase.from('customers').update({
      ...customerToUpdate,
      trainingProgress: JSON.stringify(customerToUpdate.trainingProgress)
    }).eq('id', updatedCustomer.id);
    if (error) {
        alert(`Fehler beim Speichern der Kundendaten: ${error.message}`);
    } else {
        setCustomers(prev => prev.map(c => (c.id === updatedCustomer.id ? updatedCustomer : c)));
    }
  };

  const handleAddTransaction = async (newTransaction: Omit<Transaction, 'created_at'>) => {
    if (!supabase) return;
    const { error } = await supabase.from('transactions').insert([newTransaction]);
    if (error) {
        alert(`Fehler beim Buchen der Transaktion: ${error.message}`);
    } else {
        // To properly update state, we need a complete transaction object, including created_at
        // For simplicity, we'll refetch data or just add what we have.
        // A full solution would get the created transaction back from the DB.
        const completeTransaction = { ...newTransaction, created_at: new Date().toISOString() };
        setTransactions(prev => [...prev, completeTransaction]);
    }
  };

  const handleUpdateUser = async (updatedUser: User) => {
    if (!supabase) return;
    const { error } = await supabase.from('profiles').update({
      firstName: updatedUser.firstName,
      lastName: updatedUser.lastName,
      role: updatedUser.role,
    }).eq('id', updatedUser.id);
    if (error) {
      alert(`Fehler beim Aktualisieren des Benutzers: ${error.message}`);
    } else {
      setUsers(prev => prev.map(u => (u.id === updatedUser.id ? updatedUser : u)));
      if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(prev => prev ? {...prev, ...updatedUser} : null);
      }
    }
  };

  const handleAddUser = (newUser: User) => alert("Neue Mitarbeiter müssen direkt im Supabase Dashboard unter 'Authentication' angelegt und deren Rolle im 'Table Editor' unter 'profiles' zugewiesen werden.");
  const handleDeleteUser = (userId: string) => alert("Das Löschen von Mitarbeitern muss aus Sicherheitsgründen direkt im Supabase Dashboard erfolgen.");

  const handleLogout = async () => {
    if (!supabase) return;
    await supabase.auth.signOut();
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-100">
        <div className="text-center">
          <p className="text-xl font-semibold text-gray-700">Mantrailing Card wird geladen...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-gray-100">
      {session && currentUser ? (
        <>
          <Sidebar appName="Mantrailing Card" currentUser={currentUser} onLogout={handleLogout} />
          <main className="flex-1 md:ml-64 p-0">
            <Routes>
              {currentUser.role === UserRoleEnum.ADMIN ? (
                <>
                  <Route path="/" element={<Dashboard customers={customers} transactions={transactions} />} />
                  <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="/reports" element={<Reports customers={customers} transactions={transactions} />} />
                  <Route path="/users" element={<UserManagement users={users} onAddUser={handleAddUser} onUpdateUser={handleUpdateUser} onDeleteUser={handleDeleteUser} />} />
                  <Route path="*" element={<Navigate replace to="/" />} />
                </>
              ) : currentUser.role === UserRoleEnum.MITARBEITER ? (
                <>
                  <Route path="/" element={<Dashboard customers={customers} transactions={transactions} />} />
                  <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="*" element={<Navigate replace to="/" />} />
                </>
              ) : currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId ? (
                <>
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="*" element={<Navigate replace to={`/customers/${currentUser.associatedCustomerId}`} />} />
                </>
              ) : (
                <Route path="*" element={<Navigate replace to="/login" />} />
              )}
            </Routes>
          </main>
        </>
      ) : (
        <Routes>
          <Route path="/login" element={<LoginPage onLogin={handleLogin} onRegister={handleRegister} />} />
          <Route path="*" element={<Navigate replace to="/login" />} />
        </Routes>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import Card from '../components/Card';
import StatCard from '../components/StatCard';
import Table, { Column } from '../components/Table';
import Button from '../components/Button';
import Avatar from '../components/Avatar';
import { PlusIcon, ChevronRightIcon, UsersIcon, HeartIcon, ClipboardIcon, RepeatIcon, UserPlusIcon } from '../components/Icons';
import { ALPHABET, REFERENCE_DATE } from '../constants'; // Only ALPHABET and REFERENCE_DATE remain in constants
import { Customer, CustomerTableData, TrainingLevelEnum, Transaction, User, UserRoleEnum } from '../types'; // Import types
import { useNavigate } from 'react-router-dom';
import { parseDateString, isSameMonth } from '../utils';

interface CustomerManagementProps {
  customers: Customer[];
  transactions: Transaction[];
  currentUser: User; // Added currentUser prop
}

// Helper function to get color classes based on training level for the badge
const getLevelColorClass = (level: TrainingLevelEnum) => {
  switch (level) {
    case TrainingLevelEnum.EINSTEIGER:
