  ArrowLeftIcon,
  HeartIcon,
  CreditCardIcon,
  MailIcon,
  PhoneIcon,
  AwardIcon,
  UserIcon,
  EditIcon,
  PawPrintIcon,
  TrailBadge10Icon,
  TrailBadge50Icon,
  TrailBadge100Icon,
  TrailBadge500Icon, // NEU
} from '../components/Icons';
import { CURRENT_EMPLOYEE, REFERENCE_DATE } from '../constants';
