const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [users, setUsers] = useState<User[]>([]); // For UserManagement page (staff)
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
  const [installPromptEvent, setInstallPromptEvent] = useState<any>(null);

  const navigate = useNavigate();
  const location = useLocation(); // Get current location for deep linking
  const supabase = getSupabaseClient();

  const toggleMobileSidebar = () => setIsMobileSidebarOpen(prev => !prev);
  const closeMobileSidebar = () => setIsMobileSidebarOpen(false);

  // Effect for PWA installation prompt
  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      e.preventDefault(); // Prevent the default browser prompt
      setInstallPromptEvent(e); // Store the event
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    // Clean up the event listener
    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const handleInstallClick = () => {
    if (installPromptEvent) {
      installPromptEvent.prompt(); // Show the installation prompt
      installPromptEvent.userChoice.then((choiceResult: { outcome: 'accepted' | 'dismissed' }) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('Benutzer hat die Installation akzeptiert');
        } else {
          console.log('Benutzer hat die Installation abgelehnt');
        }
        setInstallPromptEvent(null); // The prompt can only be used once
      });
    }
  };

  const handleDismissInstall = () => {
    setInstallPromptEvent(null);
  };

  // Effect 1: Manages the session from Supabase auth. This is the single source of truth for auth state.
  useEffect(() => {
    if (!supabase || USE_MOCK_DATA) {
      setIsLoading(false);
      navigate('/login');
      return;
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, [supabase, navigate]);

  // Effect 2: Fetches data when the session changes and handles post-login navigation.
  useEffect(() => {
    if (!supabase) return;

    const fetchInitialData = async (currentSession: Session) => {
      setIsLoading(true);

      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', currentSession.user.id)
        .single();

      if (profileError) {
        console.error("Error fetching user profile:", profileError);
        await supabase.auth.signOut();
        setIsLoading(false);
        return;
      }

      const loggedInUser: User = {
        id: profileData.id,
        firstName: profileData.firstName || '',
        lastName: profileData.lastName || '',
        email: profileData.email,
        role: profileData.role as UserRoleEnum,
        associatedCustomerId: profileData.associatedCustomerId,
        avatarInitials: `${(profileData.firstName || '?').charAt(0)}${(profileData.lastName || '?').charAt(0)}`.toUpperCase(),
        avatarColor: 'bg-orange-500',
        created_at: new Date(profileData.created_at || Date.now()).toLocaleDateString('de-DE'),
      };
      setCurrentUser(loggedInUser);

      if (loggedInUser.role !== UserRoleEnum.KUNDE) {
        const { data: customersData, error: customersError } = await supabase.from('customers').select('*');
        if (customersError) console.error("Error fetching customers:", customersError.message);

        const { data: transactionsData, error: transactionsError } = await supabase.from('transactions').select('*');
        if (transactionsError) console.error("Error fetching transactions:", transactionsError.message);

        setCustomers(customersData?.map(parseCustomerData) || []);
        setTransactions(transactionsData || []);

        if (loggedInUser.role === UserRoleEnum.ADMIN) {
          const { data: staffData, error: staffError } = await supabase.from('profiles').select('*').in('role', ['Admin', 'Mitarbeiter']);
           if (staffError) console.error("Error fetching staff:", staffError.message);
          setUsers(staffData?.map(p => ({
            id: p.id,
            firstName: p.firstName || '', lastName: p.lastName || '', email: p.email, role: p.role,
            associatedCustomerId: p.associatedCustomerId,
            avatarInitials: `${(p.firstName || '?').charAt(0)}${(p.lastName || '?').charAt(0)}`.toUpperCase(),
            avatarColor: 'bg-orange-500',
            created_at: new Date(p.created_at || Date.now()).toLocaleDateString('de-DE'),
          })) || []);
        }
      } else if (loggedInUser.associatedCustomerId) {
        const { data: customerData } = await supabase.from('customers').select('*').eq('id', loggedInUser.associatedCustomerId).single();
        const { data: customerTransactions } = await supabase.from('transactions').select('*').eq('customerId', loggedInUser.associatedCustomerId);
        setCustomers(customerData ? [parseCustomerData(customerData)] : []);
        setTransactions(customerTransactions || []);
      }
      setIsLoading(false);
    };

    if (session) {
      fetchInitialData(session).then(() => {
        // After data is fetched, handle redirect from login for deep linking.
        if (location.pathname === '/login') {
            const fromLocation = location.state?.from;
            const redirectTo = fromLocation ? (fromLocation.pathname + fromLocation.hash + fromLocation.search) : '/';
            navigate(redirectTo, { replace: true });
        }
      });
    } else {
      // Clear all data on logout
      setCurrentUser(null);
      setCustomers([]);
      setTransactions([]);
      setUsers([]);
      setIsLoading(false);
    }
  }, [session, supabase]);

  // Effect 3: Handles navigation for logged-in customers.
  useEffect(() => {
    if (!isLoading && session && currentUser) {
        if (currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId) {
            const expectedPath = `/customers/${currentUser.associatedCustomerId}`;
            if (window.location.hash !== `#${expectedPath}`) {
                navigate(expectedPath, { replace: true });
            }
        }
    }
  }, [isLoading, session, currentUser, navigate]);

  const handleLogin = async (email: string, passwordInput: string): Promise<string | null> => {
    if (!supabase) return "Supabase Client nicht initialisiert.";
    const { error } = await supabase.auth.signInWithPassword({ email, password: passwordInput });
    if (error) {
        console.error("Login Error:", error);
        return error.message;
    }
    return null;
  };

  const handleRegister = async (email: string, password: string): Promise<string | null> => {
    if (!supabase) return "Supabase Client nicht initialisiert.";

    // STEP 1: Define customer data
    const idPrefix = (email.split('@')[0] || 'KUNDE').substring(0, 4).toUpperCase();
    const randomSuffix = Math.floor(1000 + Math.random() * 9000);
    const associatedCustomerId = `${idPrefix}-${randomSuffix}`;
    const firstName = email.split('@')[0] || 'Neuer';
    const lastName = '(Kunde)';
    const initials = (firstName.substring(0, 2) || '??').toUpperCase();

    const targetUrl = `https://trailer-card.vercel.app/#/customers/${associatedCustomerId}`;
    const encodedTargetUrl = encodeURIComponent(targetUrl);

    const newCustomerData = {
      id: associatedCustomerId,
      avatarInitials: initials,
      avatarColor: getAvatarColorForLevel(TrainingLevelEnum.EINSTEIGER),
      firstName, lastName, email, phone: '', dogName: '', chipNumber: '',
      balance: 0, totalTransactions: 0, level: TrainingLevelEnum.EINSTEIGER,
      createdBy: 'Registrierung',
      qrCodeData: `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodedTargetUrl}`,
      documents: [],
      trainingProgress: JSON.stringify([
        { id: 1, name: TrainingLevelEnum.EINSTEIGER, requiredHours: 12, completedHours: 0, status: 'Aktuell' },
        { id: 2, name: TrainingLevelEnum.GRUNDLAGEN, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 3, name: TrainingLevelEnum.FORTGESCHRITTENE, requiredHours: 12, completedHours: 0, status: 'Gesperrt' },
        { id: 4, name: TrainingLevelEnum.MASTERCLASS, requiredHours: 13, completedHours: 0, status: 'Gesperrt' },
        { id: 5, name: TrainingLevelEnum.EXPERT, requiredHours: 100, completedHours: 0, status: 'Gesperrt' },
      ]),
    };

    // STEP 2: Create customer record
    const { error: customerInsertError } = await supabase.from('customers').insert([newCustomerData]);
    if (customerInsertError) {
      console.error("Customer Insert Error:", customerInsertError);
      return `Fehler beim Erstellen des Kundenprofils: ${customerInsertError.message}`;
    }

    // STEP 3: Create auth user
    const { data: signUpData, error: signUpError } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { firstName, lastName, role: UserRoleEnum.KUNDE, associatedCustomerId }
      }
    });

    // STEP 4: Robust error handling
    if (signUpError || !signUpData.user) {
      console.error("Sign-Up Error:", signUpError || 'Kein Benutzerobjekt zurückgegeben.');
      const { error: deleteError } = await supabase.from('customers').delete().eq('id', associatedCustomerId);
      if (deleteError) {
        console.error("CRITICAL: Fehler beim Löschen des verwaisten Kunden:", deleteError);
        return `Registrierung fehlgeschlagen und verwaister Kunde konnte nicht entfernt werden. Bitte kontaktieren Sie den Support. Fehler: ${signUpError?.message || 'Unbekannt'}`;
      }
      return `Registrierungsfehler: ${signUpError?.message || 'Benutzer konnte nicht erstellt werden.'}.`;
    }

    // Success
    return null;
  };


  const handleUpdateCustomer = async (updatedCustomer: Customer) => {
    if (!supabase) return;

    const { dataSource, ...customerToUpdate } = updatedCustomer;
    const { error: customerUpdateError } = await supabase.from('customers').update({
      ...customerToUpdate,
      trainingProgress: JSON.stringify(customerToUpdate.trainingProgress)
    }).eq('id', updatedCustomer.id);

    if (customerUpdateError) {
      alert(`Fehler beim Speichern der Kundendaten: ${customerUpdateError.message}`);
      return;
    }

    setCustomers(prev => prev.map(c => (c.id === updatedCustomer.id ? updatedCustomer : c)));

    try {
      const { data: profileData, error: profileFindError } = await supabase
        .from('profiles')
        .select('id')
        .eq('associatedCustomerId', updatedCustomer.id)
        .single();

      if (profileData && !profileFindError) {
        const userId = profileData.id;

        const { error: profileUpdateError } = await supabase
          .from('profiles')
          .update({
            firstName: updatedCustomer.firstName,
            lastName: updatedCustomer.lastName,
          })
          .eq('id', userId);

        if (profileUpdateError) {
          alert(`Kundendaten wurden gespeichert, aber das zugehörige Benutzerprofil konnte nicht aktualisiert werden: ${profileUpdateError.message}`);
        } else {
          const newAvatarInitials = `${(updatedCustomer.firstName || '?').charAt(0)}${(updatedCustomer.lastName || '?').charAt(0)}`.toUpperCase();

          setUsers(prevUsers => prevUsers.map(u => 
            u.id === userId 
              ? { ...u, firstName: updatedCustomer.firstName, lastName: updatedCustomer.lastName, avatarInitials: newAvatarInitials } 
              : u
          ));

          if (currentUser && currentUser.id === userId) {
            setCurrentUser(prev => prev ? {
              ...prev, 
              firstName: updatedCustomer.firstName, 
              lastName: updatedCustomer.lastName,
              avatarInitials: newAvatarInitials,
            } : null);
          }
        }
      } 
      else if (profileFindError && profileFindError.code !== 'PGRST116') {
          console.warn(`Fehler bei der Suche nach dem Benutzerprofil für Kunde ${updatedCustomer.id}: ${profileFindError.message}`);
      }

    } catch (e) {
      console.error("Ein unerwarteter Fehler ist beim Aktualisieren des Profils aufgetreten.", e);
    }
  };

  const handleAddTransaction = async (newTransaction: Omit<Transaction, 'created_at'>) => {
    if (!supabase) return;
    const { error } = await supabase.from('transactions').insert([newTransaction]);
    if (error) {
        alert(`Fehler beim Buchen der Transaktion: ${error.message}`);
    } else {
        const completeTransaction = { ...newTransaction, created_at: new Date().toISOString() };
        setTransactions(prev => [...prev, completeTransaction]);
    }
  };

  const handleUpdateUser = async (updatedUser: User) => {
    if (!supabase) return;
    const { error } = await supabase.from('profiles').update({
      firstName: updatedUser.firstName,
      lastName: updatedUser.lastName,
      role: updatedUser.role,
    }).eq('id', updatedUser.id);
    if (error) {
      alert(`Fehler beim Aktualisieren des Benutzers: ${error.message}`);
    } else {
      setUsers(prev => prev.map(u => (u.id === updatedUser.id ? updatedUser : u)));
      if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(prev => prev ? {...prev, ...updatedUser} : null);
      }
    }
  };

  const handleAddUser = (newUser: User) => alert("Neue Mitarbeiter müssen direkt im Supabase Dashboard unter 'Authentication' angelegt und deren Rolle im 'Table Editor' unter 'profiles' zugewiesen werden.");
  const handleDeleteUser = (userId: string) => alert("Das Löschen von Mitarbeitern muss aus Sicherheitsgründen direkt im Supabase Dashboard erfolgen.");

  const handleLogout = async () => {
    if (!supabase) return;
    await supabase.auth.signOut();
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-100">
        <div className="text-center">
          <p className="text-xl font-semibold text-gray-700">Mantrailing Card wird geladen...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-gray-100">
      {session && currentUser ? (
        <>
          <MobileHeader onToggleSidebar={toggleMobileSidebar} />
          <Sidebar
            appName="Mantrailing Card"
            currentUser={currentUser}
            onLogout={handleLogout}
            isOpen={isMobileSidebarOpen}
            onClose={closeMobileSidebar}
          />
          <main className="flex-1 md:ml-64 p-0 pt-16 md:pt-0">
            <Routes>
              {currentUser.role === UserRoleEnum.ADMIN ? (
                <>
                  <Route path="/" element={<Dashboard customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="/reports" element={<Reports customers={customers} transactions={transactions} users={users} />} />
                  <Route path="/users" element={<UserManagement users={users} onAddUser={handleAddUser} onUpdateUser={handleUpdateUser} onDeleteUser={handleDeleteUser} />} />
                  <Route path="*" element={<Navigate replace to="/" />} />
                </>
              ) : currentUser.role === UserRoleEnum.MITARBEITER ? (
                <>
                  <Route path="/" element={<Dashboard customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers" element={<CustomerManagement customers={customers} transactions={transactions} currentUser={currentUser} />} />
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="*" element={<Navigate replace to="/" />} />
                </>
              ) : currentUser.role === UserRoleEnum.KUNDE && currentUser.associatedCustomerId ? (
                <>
                  <Route path="/customers/:id" element={<CustomerDetails customers={customers} transactions={transactions} onUpdateCustomer={handleUpdateCustomer} onAddTransaction={handleAddTransaction} currentUser={currentUser} />} />
                  <Route path="*" element={<Navigate replace to={`/customers/${currentUser.associatedCustomerId}`} />} />
                </>
              ) : (
                <Route path="*" element={<Navigate replace to="/login" />} />
              )}
            </Routes>
          </main>
          {installPromptEvent && (
             <InstallPrompt onInstall={handleInstallClick} onDismiss={handleDismissInstall} />
          )}
        </>
      ) : (
        <Routes>
          <Route path="/login" element={<LoginPage onLogin={handleLogin} onRegister={handleRegister} />} />
          <Route path="*" element={<Navigate replace to="/login" state={{ from: location }} />} />
        </Routes>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import Card from '../components/Card';
import StatCard from '../components/StatCard';
import Button from '../components/Button';
import Select from '../components/Select';
import Avatar from '../components/Avatar';
import { MOCK_REPORT_TYPES, MOCK_TRANSACTION_FILTERS, REFERENCE_DATE } from '../constants';
import { ArrowUpCircleIcon, ArrowDownCircleIcon, DollarSignIcon, ClipboardIcon, UsersIcon } from '../components/Icons';
import { parseDateString, isSameMonth } from '../utils';
import { Customer, Transaction, User, UserRoleEnum } from '../types';

import jsPDF from 'jspdf';
import 'jspdf-autotable'; // Import jspdf-autotable plugin

interface ReportsProps {
  customers: Customer[];
  transactions: Transaction[];
  users: User[];
}

// Helper function to generate dynamic report periods
const generateReportPeriods = (reportType: string, referenceDate: Date) => {
  const periods = [];
  const currentMonthName = referenceDate.toLocaleString('de-DE', { month: 'long' });
  const currentYear = referenceDate.getFullYear();

  if (reportType === 'Monatlich') {
    // Current month
    periods.push({ value: `${currentMonthName.charAt(0).toUpperCase() + currentMonthName.slice(1)} ${currentYear}`, label: `${currentMonthName.charAt(0).toUpperCase() + currentMonthName.slice(1)} ${currentYear}` });

    // Previous month
    const prevMonthDate = new Date(referenceDate);
    prevMonthDate.setMonth(referenceDate.getMonth() - 1);
    const prevMonthName = prevMonthDate.toLocaleString('de-DE', { month: 'long' });
    const prevMonthYear = prevMonthDate.getFullYear();
    periods.push({ value: `${prevMonthName.charAt(0).toUpperCase() + prevMonthName.slice(1)} ${prevMonthYear}`, label: `${prevMonthName.charAt(0).toUpperCase() + prevMonthName.slice(1)} ${prevMonthYear}` });

  } else if (reportType === 'Jährlich') {
    // Current year
    periods.push({ value: String(currentYear), label: String(currentYear) });

    // Previous year
    periods.push({ value: String(currentYear - 1), label: String(currentYear - 1) });
  } else if (reportType === 'Benutzerdefiniert') {
    // For now, "Gesamt" represents a custom, all-encompassing period
    periods.push({ value: 'Gesamt', label: 'Gesamt' });
  }
  return periods;
};


const Reports: React.FC<ReportsProps> = ({ customers, transactions, users }) => {
  const [reportType, setReportType] = useState('Monatlich');
  const [employee, setEmployee] = useState('Alle Mitarbeiter');
  const [transactionFilter, setTransactionFilter] = useState('Alle Transaktionen'); // New state for transaction type filter

  const initialPeriods = generateReportPeriods('Monatlich', REFERENCE_DATE);
  const [timePeriod, setTimePeriod] = useState(initialPeriods.length > 0 ? initialPeriods[0].value : 'Gesamt');
  const [availableTimePeriods, setAvailableTimePeriods] = useState(initialPeriods);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Effect to update availableTimePeriods and reset timePeriod when reportType changes
  useEffect(() => {
    const newPeriods = generateReportPeriods(reportType, REFERENCE_DATE);
    setAvailableTimePeriods(newPeriods);
    if (newPeriods.length > 0) {
      setTimePeriod(newPeriods[0].value); // Set to the first option by default
    } else {
      setTimePeriod('Gesamt'); // Fallback
    }
  }, [reportType]);

  // Dynamically generate employee options from the users prop
  const employeeOptions = useMemo(() => {
    const staff = users
      .filter(u => u.role === UserRoleEnum.ADMIN || u.role === UserRoleEnum.MITARBEITER)
      .map(u => ({
        value: `${u.firstName} ${u.lastName}`,
        label: `${u.firstName} ${u.lastName}`,
      }));
    return [{ value: 'Alle Mitarbeiter', label: 'Alle Mitarbeiter' }, ...staff];
  }, [users]);


  // Helper for parsing current filter period
  const getFilterPeriodDate = () => {
    if (timePeriod === 'Gesamt') return null;

    // Check if it's a year (e.g., "2025")
    if (!isNaN(parseInt(timePeriod, 10)) && timePeriod.length === 4) {
      return new Date(parseInt(timePeriod, 10), 0, 1); // January 1st of the year
    }

    // Assume "Month YYYY" format for detailed filtering
    const [monthName, year] = timePeriod.split(' ');
    const monthMap: { [key: string]: number } = {
      'Januar': 0, 'Februar': 1, 'März': 2, 'April': 3, 'Mai': 4, 'Juni': 5,
      'Juli': 6, 'August': 7, 'September': 8, 'Oktober': 9, 'November': 10, 'Dezember': 11
    };
    const monthIndex = monthMap[monthName];
    if (monthIndex !== undefined && year) {
      return new Date(parseInt(year, 10), monthIndex, 1);
    }
    return null;
  };

  const selectedFilterPeriod = getFilterPeriodDate();

  // Filter transactions based on selected criteria
  const filteredTransactions = transactions.filter(t => {
    const transactionDate = parseDateString(t.date);
    if (!transactionDate) return false;

    // Filter by period
    let matchesPeriod = true;
    if (timePeriod === 'Gesamt') {
      matchesPeriod = true;
    } else if (reportType === 'Monatlich' && selectedFilterPeriod) {
      matchesPeriod = isSameMonth(transactionDate, selectedFilterPeriod);
    } else if (reportType === 'Jährlich' && selectedFilterPeriod) {
      matchesPeriod = transactionDate.getFullYear() === selectedFilterPeriod.getFullYear();
    }


    // Filter by employee
    const matchesEmployee = employee === 'Alle Mitarbeiter' || t.employee === employee;

    // Filter by transaction type
    let matchesTransactionType = true;
    if (transactionFilter === 'Einnahmen (Aufladungen)') {
      matchesTransactionType = t.type === 'recharge';
    } else if (transactionFilter === 'Ausgaben (Abbuchungen)') {
      matchesTransactionType = t.type === 'debit';
    }

    return matchesPeriod && matchesEmployee && matchesTransactionType;
  });

  // Dynamic calculations for Report Stats
  const monthlyRecharges = filteredTransactions
    .filter(t => t.type === 'recharge')
    .reduce((sum, t) => sum + Math.abs(t.amount), 0);

  const monthlyDebits = filteredTransactions
    .filter(t => t.type === 'debit')
    .reduce((sum, t) => sum + Math.abs(t.amount), 0);

  const totalMonthlyTransactions = filteredTransactions.length;

  const activeCustomerIdsInPeriod = new Set(
    filteredTransactions.map(t => t.customerId)
  );
  const activeCustomersInPeriodCount = customers.filter(c => activeCustomerIdsInPeriod.has(c.id)).length;


  const getTopCustomers = () => {
    const customerTransactions: { [key: string]: { count: number; totalAmount: number } } = {};
    filteredTransactions.forEach(t => {
      if (!customerTransactions[t.customerId]) {
        customerTransactions[t.customerId] = { count: 0, totalAmount: 0 };
      }
      customerTransactions[t.customerId].count++;
      customerTransactions[t.customerId].totalAmount += Math.abs(t.amount);
    });

    return Object.entries(customerTransactions)
      .sort(([, a], [, b]) => b.totalAmount - a.totalAmount)
      .slice(0, 3)
      .map(([customerId, data]) => {
        const customer = customers.find(c => c.id === customerId);
        return {
          customerName: customer ? `${customer.firstName} ${customer.lastName}` : 'Unbekannt',
          dogName: customer?.dogName || '',
          transactionCount: data.count,
          totalAmount: data.totalAmount,
          avatarInitials: customer?.avatarInitials || '?',
          avatarColor: customer?.avatarColor || 'bg-gray-400',
          id: customerId,
        };
      });
  };

  const topCustomers = getTopCustomers();

  const handleExportPdf = async () => {
    setIsGeneratingPdf(true);
    try {
      const doc = new jsPDF();
      let yPos = 20;

      // Report Title
      doc.setFontSize(22);
      doc.text(`Mantrailing Card App - ${reportType} Bericht`, 105, yPos, { align: 'center' });
      yPos += 10;
      doc.line(20, yPos, 190, yPos); // Horizontal line
      yPos += 10;

      // Filter Details
      doc.setFontSize(12);
      doc.text(`Berichtstyp: ${reportType}`, 20, yPos);
      yPos += 7;
      doc.text(`Zeitraum: ${timePeriod}`, 20, yPos);
      yPos += 7;
      doc.text(`Mitarbeiter: ${employee}`, 20, yPos);
      yPos += 7;
      doc.text(`Transaktionstyp: ${transactionFilter}`, 20, yPos); // Add transaction filter to PDF
      yPos += 7;
      doc.text(`Erstellt am: ${REFERENCE_DATE.toLocaleDateString('de-DE')}`, 20, yPos);
      yPos += 15;

      // Summary Stats
      doc.setFontSize(16);
      doc.text('Übersicht', 20, yPos);
      yPos += 7;
      doc.setFontSize(12);
      doc.text(`Gesamtaufladungen: ${monthlyRecharges.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}`, 20, yPos);
      yPos += 7;
      doc.text(`Abbuchungen: ${monthlyDebits.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}`, 20, yPos);
      yPos += 7;
      doc.text(`Anzahl Transaktionen: ${totalMonthlyTransactions}`, 20, yPos);
      yPos += 7;
      doc.text(`Aktive Kunden: ${activeCustomersInPeriodCount}`, 20, yPos);
      yPos += 15;

      // Transactions Table
      doc.setFontSize(16);
      doc.text(`${transactionFilter} im Zeitraum`, 20, yPos); // Dynamic title based on filter
      yPos += 5;

      const transactionsHeaders = [['Datum', 'Beschreibung', 'Kunde', 'Mitarbeiter', 'Typ', 'Betrag']];
      const transactionsData = filteredTransactions.map(t => {
        const customer = customers.find(c => c.id === t.customerId);
        const customerName = customer ? `${customer.firstName} ${customer.lastName}` : 'Unbekannt';
        const isRecharge = t.type === 'recharge';
        const amountSign = isRecharge ? '+' : '-';
        const formattedAmount = `${amountSign}${Math.abs(t.amount).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}`;
        return [t.date, t.description, customerName, t.employee, t.type === 'recharge' ? 'Aufladung' : 'Abbuchung', formattedAmount];
      });

      (doc as any).autoTable({
        startY: yPos,
        head: transactionsHeaders,
        body: transactionsData,
        theme: 'striped',
        headStyles: { fillColor: [0, 161, 214] }, // Blue color for header
        margin: { top: 10, right: 20, bottom: 10, left: 20 },
        didParseCell: function (data: any) {
          if (data.section === 'body' && data.column.index === 5) { // Amount column
            const amountStr = data.cell.text[0];
            if (amountStr && amountStr.startsWith('+')) {
              data.cell.styles.textColor = [34, 139, 34]; // Green for recharge
            } else if (amountStr && amountStr.startsWith('-')) {
              data.cell.styles.textColor = [220, 20, 60]; // Red for debit
            }
          }
        },
      });

      yPos = (doc as any).autoTable.previous.finalY + 15;

      // Top Customers Table
      doc.setFontSize(16);
      doc.text('Top Kunden im Zeitraum', 20, yPos);
      yPos += 5;

      const topCustomersHeaders = [['Rang', 'Kunde', 'Hund', 'Transaktionen', 'Gesamtbetrag']];
      const topCustomersData = topCustomers.map((c, index) => [
        index + 1,
        c.customerName,
        c.dogName,
        c.transactionCount,
        c.totalAmount.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }),
      ]);

      (doc as any).autoTable({
        startY: yPos,
        head: topCustomersHeaders,
        body: topCustomersData,
        theme: 'striped',
        headStyles: { fillColor: [0, 161, 214] }, // Blue color for header
        margin: { top: 10, right: 20, bottom: 10, left: 20 },
      });

      const fileName = `Bericht_${reportType.replace(' ', '_')}_${timePeriod.replace(' ', '_')}_${employee.replace(' ', '_')}_${transactionFilter.replace(' ', '_')}.pdf`;
      doc.save(fileName);
      alert('PDF Export erfolgreich!');
    } catch (error) {
      console.error("Fehler beim Erstellen der PDF:", error);
      alert('Fehler beim PDF Export. Bitte versuchen Sie es erneut.');
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  return (
    <div className="p-6 md:p-8 lg:p-10">
      <h1 className="text-3xl font-bold text-gray-900 mb-2">Berichte & Statistiken</h1>
      <p className="text-gray-600 mb-8">Analysieren und exportieren Sie Ihre Geschäftsdaten</p>

      {/* Filters and Export Button */}
      <Card className="mb-8">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
          <Select
            id="reportType"
            label="Berichtstyp"
            options={MOCK_REPORT_TYPES.map(type => ({ value: type, label: type }))}
            value={reportType}
            onChange={(e) => setReportType(e.target.value)}
            disabled={isGeneratingPdf}
          />
          <Select
            id="timePeriod"
            label="Zeitraum"
            options={availableTimePeriods}
            value={timePeriod}
            onChange={(e) => setTimePeriod(e.target.value)}
            disabled={isGeneratingPdf}
          />
          <Select
            id="employee"
            label="Mitarbeiter"
            options={employeeOptions}
            value={employee}
            onChange={(e) => setEmployee(e.target.value)}
            disabled={isGeneratingPdf}
          />
          <Select
            id="transactionFilter"
            label="Transaktionstyp"
            options={MOCK_TRANSACTION_FILTERS.map(filter => ({ value: filter, label: filter }))}
            value={transactionFilter}
            onChange={(e) => setTransactionFilter(e.target.value)}
            disabled={isGeneratingPdf}
          />
          {/* Button moved to the last position in the grid to appear bottom-right */}
          <Button 
            variant="success" 
            className="w-full sm:col-span-1 lg:col-start-4 lg:col-span-1 lg:w-auto"
            onClick={handleExportPdf}
            disabled={isGeneratingPdf}
          >
            {isGeneratingPdf ? 'PDF wird generiert...' : 'Als PDF exportieren'}
          </Button>
        </div>
      </Card>

      {/* Stats Cards for Reports */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <StatCard
          title="Gesamtaufladungen"
          value={monthlyRecharges.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' })}
          icon={UsersIcon}
          color="bg-green-100 text-green-700"
        />
        <StatCard
          title="Abbuchungen"
