              <div className={`${trainingInfo.cardClasses.bg} p-4 rounded-lg flex flex-col justify-center items-center text-center`}>
                <p className="text-sm text-gray-600 mb-1">Fortschritt</p>
                <div className="flex items-center mt-2">
